/* =====================================================================
   HEARD — Design System Foundations
   Companionship marketplace. Warm, trustworthy, accessible-first.
   Body text ≥ 18px. Contrast AA floor, AAA on body where feasible.
   ===================================================================== */

/* ---- Fonts ---------------------------------------------------------- */
/* Nunito (display/headings) + Nunito Sans (body). Humanist, rounded,
   highly legible — chosen for an older / low-vision audience.
   Loaded via Google Fonts CDN. See README "Typography". */
@import url('https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&family=Nunito+Sans:opsz,wght@6..12,400;6..12,600;6..12,700&display=swap');

:root {
  /* ---- Color: brand palette (exact tokens from brief) ------------- */
  --bg:            #FBF7F2;  /* warm off-white page background          */
  --surface:       #FFFFFF;  /* cards, sheets                          */
  --surface-sunk:  #F4EEE5;  /* recessed wells, track backgrounds      */

  --ink:           #2A2622;  /* primary text (warm near-black)         */
  --ink-soft:      #6B6259;  /* secondary text                        */
  --ink-faint:     #948B81;  /* tertiary / placeholder                 */

  --primary:       #136F63;  /* calm teal — trust; primary buttons     */
  --primary-dark:  #0E5249;  /* hover / active                        */
  --primary-tint:  #E4EFEC;  /* teal wash — selected chips, fills      */

  --accent:        #E08A3C;  /* warm amber — tips, gentle highlights   */
  --accent-dark:   #C4732C;  /* amber hover / active                   */
  --accent-tint:   #FBEBD9;  /* amber wash                            */

  --success:       #2E7D5B;  /* available / positive (pair w/ text)    */
  --success-tint:  #E3F0EA;
  --alert:         #B23A2E;  /* errors / safety (pair w/ text)         */
  --alert-tint:    #F7E6E3;

  --border:        #ECE3D8;  /* hairlines, dividers                    */
  --border-strong: #D9CCBC;  /* input borders, stronger separation     */
  --focus:         #1B6FB0;  /* high-visibility focus ring (3px)       */

  /* ---- Type families --------------------------------------------- */
  --font-display: 'Lora', Georgia, 'Times New Roman', serif;  /* warm humanist serif — headings */
  --font-body:    'Nunito Sans', system-ui, -apple-system, sans-serif;

  /* ---- Type scale (px). Body floor = 18px ------------------------ */
  --text-xs:   14px;   /* meta / fine print — use sparingly          */
  --text-sm:   16px;   /* labels, secondary                         */
  --text-base: 18px;   /* BODY MINIMUM                              */
  --text-lg:   20px;   /* large body / lead                         */
  --text-h3:   24px;
  --text-h2:   30px;
  --text-h1:   38px;
  --text-display: 46px;

  --leading-tight: 1.2;
  --leading-snug:  1.35;
  --leading-body:  1.6;   /* generous body line-height               */

  --weight-regular: 400;
  --weight-semibold: 600;
  --weight-bold: 700;
  --weight-extrabold: 800;

  /* ---- Spacing — 8px grid ---------------------------------------- */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-7: 48px;
  --space-8: 64px;
  --space-9: 96px;

  /* ---- Radii ----------------------------------------------------- */
  --radius-sm:   8px;
  --radius-btn:  12px;   /* buttons                                  */
  --radius-card: 16px;   /* cards, sheets                            */
  --radius-lg:   24px;   /* large surfaces / hero                    */
  --radius-pill: 999px;  /* chips, toggles, avatars                  */

  /* ---- Shadows — soft, low, warm --------------------------------- */
  --shadow-xs: 0 1px 2px rgba(42, 38, 34, 0.05);
  --shadow-sm: 0 2px 8px rgba(42, 38, 34, 0.06);
  --shadow-md: 0 6px 20px rgba(42, 38, 34, 0.08);
  --shadow-lg: 0 14px 40px rgba(42, 38, 34, 0.12);

  /* ---- Focus ring — never removed -------------------------------- */
  --focus-ring: 0 0 0 3px var(--focus);
  --focus-ring-offset: 0 0 0 2px var(--surface), 0 0 0 5px var(--focus);

  /* ---- Min interactive target ------------------------------------ */
  --tap-min: 48px;

  /* ---- Motion (gentle; respect reduced-motion) ------------------- */
  --ease: cubic-bezier(0.33, 0.1, 0.25, 1);
  --dur-fast: 120ms;
  --dur: 200ms;
  --dur-slow: 320ms;
}

/* =====================================================================
   SEMANTIC ELEMENT DEFAULTS
   Drop colors_and_type.css into any page to get on-brand baselines.
   ===================================================================== */

body {
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: var(--leading-body);
  font-weight: var(--weight-regular);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

h1, h2, h3, h4 {
  font-family: var(--font-display);
  color: var(--ink);
  line-height: var(--leading-tight);
  text-wrap: balance;
  margin: 0;
}
h1 { font-size: var(--text-h1); font-weight: 700; letter-spacing: -0.01em; }
h2 { font-size: var(--text-h2); font-weight: 700; letter-spacing: -0.01em; }
h3 { font-size: var(--text-h3); font-weight: var(--weight-bold); }

p  { margin: 0; text-wrap: pretty; }
.lead { font-size: var(--text-lg); color: var(--ink-soft); line-height: var(--leading-body); }
.meta { font-size: var(--text-sm); color: var(--ink-soft); }

a { color: var(--primary); text-underline-offset: 3px; }
a:hover { color: var(--primary-dark); }

/* ---- Universal visible focus — the single most important rule ----- */
:where(a, button, input, select, textarea, [tabindex], [role="button"], [role="tab"]):focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: var(--radius-sm);
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

