######## ui.jsx ########
/* Heard UI kit — shared primitives. Exports to window. */
const { useState, useEffect, useRef } = React;

/* ---- Icon: React-owned span, Lucide draws the SVG inside ----------- */
function Icon({ name, size = 20, color, strokeWidth = 2, style = {} }) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (el && window.lucide && window.lucide.icons) {
      el.innerHTML = '';
      const i = document.createElement('i');
      i.setAttribute('data-lucide', name);
      el.appendChild(i);
      window.lucide.createIcons({ attrs: { 'stroke-width': strokeWidth }, nameAttr: 'data-lucide' });
    }
  }, [name, strokeWidth]);
  return <span ref={ref} aria-hidden="true"
    style={{ width: size, height: size, display: 'inline-flex', color, flex: 'none', ...style }} className="lic" />;
}

/* ---- Button -------------------------------------------------------- */
function Button({ variant = 'primary', icon, children, full, onClick, ariaLabel, type = 'button' }) {
  const base = {
    fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: 18, minHeight: 'var(--tap-min)',
    padding: '10px 22px', borderRadius: 'var(--radius-btn)', border: '1px solid transparent',
    cursor: 'pointer', display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
    gap: 10, width: full ? '100%' : 'auto', transition: 'background var(--dur) var(--ease)', lineHeight: 1.2,
    whiteSpace: 'nowrap', flex: full ? undefined : 'none',
  };
  const v = {
    primary: { background: 'var(--primary)', color: '#fff' },
    amber:   { background: 'var(--accent)', color: '#fff' },
    ghost:   { background: 'var(--surface)', color: 'var(--primary)', borderColor: 'var(--border-strong)' },
    danger:  { background: 'var(--alert)', color: '#fff' },
    quiet:   { background: 'transparent', color: 'var(--primary)', textDecoration: 'underline', textUnderlineOffset: 3, minHeight: 'auto', padding: '8px 6px' },
  }[variant];
  return (
    <button type={type} onClick={onClick} aria-label={ariaLabel}
      className={`btn-${variant}`} style={{ ...base, ...v }}>
      {icon && <Icon name={icon} size={20} />}{children}
    </button>
  );
}

/* ---- Avatar -------------------------------------------------------- */
function Avatar({ listener, size = 56 }) {
  return (
    <div aria-hidden="true" style={{
      width: size, height: size, borderRadius: '50%', flex: 'none', background: listener.color,
      color: '#fff', display: 'grid', placeItems: 'center',
      fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: size * 0.42,
    }}>{listener.firstName[0]}</div>
  );
}

/* ---- Availability pill (icon + text, never color alone) ------------ */
function Availability({ status }) {
  const map = {
    available: { c: 'var(--success)', bg: 'var(--success-tint)', icon: 'circle-check', label: 'Available now' },
    busy:      { c: 'var(--ink-soft)', bg: 'var(--surface-sunk)', icon: 'clock', label: 'In a session' },
    scheduled: { c: 'var(--accent-dark)', bg: 'var(--accent-tint)', icon: 'calendar', label: 'Scheduled only' },
  }[status];
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6, fontSize: 14, fontWeight: 700, whiteSpace: 'nowrap',
      color: map.c, background: map.bg, padding: '4px 10px', borderRadius: 'var(--radius-pill)' }}>
      <Icon name={map.icon} size={15} /> {map.label}
    </span>
  );
}

/* ---- Chip (toggle) ------------------------------------------------- */
function Chip({ children, selected, onClick }) {
  return (
    <button type="button" onClick={onClick} aria-pressed={!!selected}
      style={{
        fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: 16, minHeight: 44, padding: selected ? '0 16px' : '0 17px',
        borderRadius: 'var(--radius-pill)', cursor: 'pointer',
        border: selected ? '2px solid var(--primary)' : '1px solid var(--border-strong)',
        background: selected ? 'var(--primary-tint)' : 'var(--surface)',
        color: selected ? 'var(--primary-dark)' : 'var(--ink)',
        display: 'inline-flex', alignItems: 'center', gap: 7,
      }}>
      {selected && <Icon name="check" size={16} />}{children}
    </button>
  );
}

/* ---- Voice intro player (simulated) -------------------------------- */
function VoicePlayer({ listener, big, announce }) {
  const [playing, setPlaying] = useState(false);
  const toggle = () => {
    const next = !playing; setPlaying(next);
    announce && announce(next ? `Playing ${listener.firstName}'s voice intro` : 'Paused');
  };
  const d = big ? 64 : 48;
  return (
    <div style={{ display: 'flex', flexDirection: big ? 'column' : 'row', alignItems: big ? 'stretch' : 'center', gap: 14, background: 'var(--surface)',
      border: '1px solid var(--border)', borderRadius: 'var(--radius-card)', padding: big ? 16 : 12, boxShadow: 'var(--shadow-sm)' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 14, flex: 1, minWidth: 0 }}>
        <button type="button" onClick={toggle}
          aria-label={playing ? `Pause ${listener.firstName}'s voice intro` : `Play ${listener.firstName}'s voice intro`}
          style={{ width: d, height: d, flex: 'none', borderRadius: '50%', border: 'none', cursor: 'pointer',
            background: playing ? 'var(--primary-dark)' : 'var(--primary)', color: '#fff', display: 'grid', placeItems: 'center' }}>
          <Icon name={playing ? 'pause' : 'play'} size={big ? 28 : 22} />
        </button>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontWeight: 700, fontSize: big ? 18 : 16, color: 'var(--ink)' }}>
            {listener.firstName}'s voice intro
          </div>
          <div style={{ fontSize: 14, color: 'var(--ink-soft)', display: 'flex', alignItems: 'center', gap: 8 }}>
            {playing ? <React.Fragment><Waveform /> <span>Playing…</span></React.Fragment> : <span>0:24 · tap to listen</span>}
          </div>
        </div>
      </div>
      {big && <p style={{ fontSize: 16, color: 'var(--ink)', lineHeight: 1.5, margin: 0 }}>
        <span style={{ fontWeight: 700, color: 'var(--ink-soft)', fontSize: 13, display: 'block', marginBottom: 2 }}>Transcript</span>
        {listener.intro}</p>}
    </div>
  );
}

function Waveform() {
  const bars = [8, 18, 12, 20, 9, 15, 22, 11];
  return (
    <span aria-hidden="true" style={{ display: 'inline-flex', alignItems: 'center', gap: 3, height: 22 }} className="wf">
      {bars.map((h, i) => <span key={i} style={{ width: 3, height: h, background: 'var(--accent)', borderRadius: 2,
        animation: 'wf 0.9s var(--ease) infinite alternate', animationDelay: `${i * 0.08}s` }} />)}
    </span>
  );
}

/* ---- Persistent safety note ---------------------------------------- */
function SafetyNote({ onOpen }) {
  return (
    <div role="note" style={{ display: 'flex', alignItems: 'flex-start', gap: 10, background: 'var(--surface)',
      border: '1px solid var(--border)', borderLeft: '4px solid var(--primary)', borderRadius: 'var(--radius-card)',
      padding: '12px 14px', boxShadow: 'var(--shadow-xs)' }}>
      <Icon name="shield-check" size={20} color="var(--primary)" style={{ marginTop: 2 }} />
      <div style={{ fontSize: 15, color: 'var(--ink)', lineHeight: 1.5 }}>
        This is companionship, not medical or mental-health care.{' '}
        <button type="button" onClick={onOpen} style={{ background: 'none', border: 'none', padding: 0, cursor: 'pointer',
          color: 'var(--primary)', fontWeight: 700, fontFamily: 'inherit', fontSize: 15, textDecoration: 'underline', textUnderlineOffset: 3 }}>
          If you're in crisis, we'll help you find support</button>.
      </div>
    </div>
  );
}

/* ---- Screen header with back -------------------------------------- */
function ScreenHeader({ title, onBack }) {
  return (
    <header style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 0 14px' }}>
      {onBack && (
        <button type="button" onClick={onBack} aria-label="Go back"
          style={{ display: 'inline-flex', alignItems: 'center', gap: 4, background: 'none', border: 'none', cursor: 'pointer',
            color: 'var(--primary)', fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: 16, padding: 8, marginLeft: -8 }}>
          <Icon name="chevron-left" size={20} /> Back
        </button>
      )}
      {title && <h2 style={{ fontSize: 20, marginLeft: onBack ? 4 : 0 }}>{title}</h2>}
    </header>
  );
}

Object.assign(window, { Icon, Button, Avatar, Availability, Chip, VoicePlayer, Waveform, SafetyNote, ScreenHeader });
######## data.jsx ########
