    reviewsList: [ { by: 'S.', text: 'Felt like catching up with an old friend.' } ] },
  { id: 'omar',  firstName: 'Omar',  color: '#4A6FA5',
    intro: "Omar here. Late nights, quiet talks, or just sitting with a thought together — whatever helps. I'm glad you're here.",
    tags: ['just listen', 'night owl', 'transition'], languages: ['English', 'Arabic'],
    rating: 4.9, reviews: 112, pricePerMin: 0.8, status: 'available',
    reviewsList: [ { by: 'L.', text: 'Omar made a hard night a lot lighter.' } ] },
];

const TOPICS = ['everyday chat', 'just listen', 'grief', 'books', 'sports', 'language practice', 'night owl', 'transition'];

const STATUS_LABEL = { available: 'Available now', busy: 'In a session', scheduled: 'Scheduled only' };

function priceFor(durationMin, pricePerMin) {
  return Math.round(durationMin * pricePerMin);
}
function fmtTime(totalSec) {
  const m = Math.floor(totalSec / 60), s = totalSec % 60;
  return `${m}:${String(s).padStart(2, '0')}`;
}

Object.assign(window, { LISTENERS, TOPICS, STATUS_LABEL, priceFor, fmtTime });

