 * layout). States plainly that Heard is companionship, not therapy, and opens a
 * calm crisis-support dialog — reachable from every screen (SPEC §10).
 */
export function SafetyBanner() {
  const [open, setOpen] = React.useState(false);

  return (
    <>
      <footer className="mt-auto border-t border-border bg-surface">
