-- =====================================================================
-- M0 — auth foundation: profiles + minimal providers, with RLS.
-- The full data model (availability, bookings, sessions, payments, …)
-- lands in M1. Here we only need enough for sign-up + role persistence.
-- =====================================================================

-- ---- Enums ----------------------------------------------------------
create type public.user_role as enum ('customer', 'provider', 'admin');
create type public.provider_status as enum ('pending', 'approved', 'rejected', 'suspended');
create type public.bg_check_status as enum ('pending', 'clear', 'consider');

-- ---- updated_at helper ---------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- ---- profiles -------------------------------------------------------
create table public.profiles (
  id         uuid primary key references auth.users (id) on delete cascade,
  role       public.user_role not null default 'customer',
  full_name  text not null default '',
  email      text not null default '',
  locale     text not null default 'en',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

-- ---- providers (minimal for M0; expanded in M1) ---------------------
create table public.providers (
  id              uuid primary key references public.profiles (id) on delete cascade,
  display_name    text not null default '',
  status          public.provider_status not null default 'pending',
  bg_check_status public.bg_check_status not null default 'pending',
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

create trigger providers_set_updated_at
  before update on public.providers
  for each row execute function public.set_updated_at();

-- ---- Admin check (SECURITY DEFINER avoids recursive RLS on profiles)-
create or replace function public.is_admin()
returns boolean
language sql
security definer
set search_path = public
stable
as $$
  select exists (
    select 1 from public.profiles
    where id = auth.uid() and role = 'admin'
  );
$$;

-- ---- Create profile (+ provider) on sign-up -------------------------
-- Role and name arrive in the user's raw_user_meta_data at signUp time.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_role public.user_role;
  v_name text;
begin
  v_role := coalesce(
    (new.raw_user_meta_data ->> 'role')::public.user_role,
    'customer'
  );
  v_name := coalesce(new.raw_user_meta_data ->> 'full_name', '');

  insert into public.profiles (id, role, full_name, email)
  values (new.id, v_role, v_name, coalesce(new.email, ''));

  if v_role = 'provider' then
    insert into public.providers (id, display_name, status, bg_check_status)
    values (new.id, v_name, 'pending', 'pending');
  end if;

  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---- Row-Level Security --------------------------------------------
alter table public.profiles enable row level security;
alter table public.providers enable row level security;

-- profiles: a user reads/updates only their own row; admins see all.
create policy "profiles_select_own"
  on public.profiles for select
  using (id = auth.uid() or public.is_admin());

create policy "profiles_update_own"
  on public.profiles for update
  using (id = auth.uid() or public.is_admin())
  with check (id = auth.uid() or public.is_admin());

-- providers: owner reads own; anyone reads approved; admins all.
create policy "providers_select_public_or_own"
  on public.providers for select
  using (
    status = 'approved'
    or id = auth.uid()
    or public.is_admin()
  );

create policy "providers_update_own_or_admin"
  on public.providers for update
  using (id = auth.uid() or public.is_admin())
  with check (id = auth.uid() or public.is_admin());

