import { Card } from "@/components/ui/Card";
import { getProfile } from "@/lib/auth";
import { t } from "@/lib/i18n";
import { type MessageKey } from "@/lib/i18n";

/**
 * Lightweight placeholder for routes whose full UI lands in a later milestone.
 * Renders the signed-in identity so role persistence is visible end-to-end in
 * M0 (the dashboard/queue/etc. replace this in M3–M7).
 */
export async function ComingSoon({
  titleKey,
  bodyKey,
}: {
  titleKey: MessageKey;
  bodyKey: MessageKey;
}) {
  const profile = await getProfile();

  return (
    <div className="flex flex-col gap-5">
      <h1 className="text-h1">{t(titleKey)}</h1>
      <Card className="flex flex-col gap-3">
        <p className="text-lg text-ink">{t(bodyKey)}</p>
        {profile ? (
          <p className="text-base text-ink-soft">
            {t("page.signedInAs", {
              name: profile.full_name || profile.email,
              role: profile.role,
            })}
          </p>
        ) : null}
      </Card>
    </div>
  );
}

