import { describe, it, expect } from "vitest";
import { t } from "@/lib/i18n";

describe("i18n t()", () => {
  it("resolves a nested key to its string", () => {
    expect(t("app.name")).toBe("Heard");
  });

  it("interpolates named variables", () => {
    expect(t("ui.playVoiceIntro", { name: "Maya" })).toBe(
      "Play Maya's voice intro",
    );
  });

  it("leaves unknown placeholders intact", () => {
    // page.signedInAs uses {name} and {role}; supplying only one keeps the other.
    expect(t("page.signedInAs", { name: "Sam" })).toContain("{role}");
  });

  it("returns the key itself when the message is missing", () => {
    // @ts-expect-error — intentionally testing a non-existent key at runtime.
    expect(t("does.not.exist")).toBe("does.not.exist");
  });
});

