import { describe, it, expect } from "vitest";
import { signUpSchema, signInSchema } from "@/lib/validation/schemas";

describe("signUpSchema", () => {
  it("accepts a valid customer sign-up", () => {
    const result = signUpSchema.safeParse({
      fullName: "Sam Rivera",
      email: "sam@example.com",
      password: "supersecret",
      role: "customer",
    });
    expect(result.success).toBe(true);
  });

  it("accepts a valid provider sign-up", () => {
    const result = signUpSchema.safeParse({
      fullName: "Maya Lin",
      email: "maya@example.com",
      password: "longenough",
      role: "provider",
    });
    expect(result.success).toBe(true);
  });

  it("rejects a short password", () => {
    const result = signUpSchema.safeParse({
      fullName: "Sam",
      email: "sam@example.com",
      password: "short",
      role: "customer",
    });
    expect(result.success).toBe(false);
  });

  it("rejects an invalid email", () => {
    const result = signUpSchema.safeParse({
      fullName: "Sam",
      email: "not-an-email",
      password: "longenough",
      role: "customer",
    });
    expect(result.success).toBe(false);
  });

  it("rejects an unknown role (e.g. admin self-signup)", () => {
    const result = signUpSchema.safeParse({
      fullName: "Sam",
      email: "sam@example.com",
      password: "longenough",
      role: "admin",
    });
    expect(result.success).toBe(false);
  });

  it("trims the name", () => {
    const result = signUpSchema.safeParse({
      fullName: "  Sam Rivera  ",
      email: "sam@example.com",
      password: "longenough",
      role: "customer",
    });
    expect(result.success && result.data.fullName).toBe("Sam Rivera");
  });
});

describe("signInSchema", () => {
  it("requires a non-empty password", () => {
    const result = signInSchema.safeParse({
      email: "sam@example.com",
      password: "",
    });
    expect(result.success).toBe(false);
  });
});

