    const result = signUpSchema.safeParse({
      fullName: "Sam",
      email: "sam@example.com",
      password: "short",
      role: "customer",
    });
    expect(result.success).toBe(false);
  });

  it("rejects an invalid email", () => {
    const result = signUpSchema.safeParse({
      fullName: "Sam",
      email: "not-an-email",
      password: "longenough",
      role: "customer",
    });
    expect(result.success).toBe(false);
  });

  it("rejects an unknown role (e.g. admin self-signup)", () => {
    const result = signUpSchema.safeParse({
      fullName: "Sam",
      email: "sam@example.com",
      password: "longenough",
      role: "admin",
    });
