/**
 * Minimal hand-written database types for M0 (profiles + providers).
 * The full schema lands in M1 and these will be replaced by types generated
 * from the database via `supabase gen types`.
 */

export type UserRole = "customer" | "provider" | "admin";
export type ProviderStatus = "pending" | "approved" | "rejected" | "suspended";
export type BgCheckStatus = "pending" | "clear" | "consider";

export interface ProfileRow {
  id: string;
  role: UserRole;
  full_name: string;
  email: string;
  locale: string;
  created_at: string;
  updated_at: string;
}

export interface ProviderRow {
  id: string;
  display_name: string;
  status: ProviderStatus;
  bg_check_status: BgCheckStatus | null;
  created_at: string;
  updated_at: string;
}

export interface Database {
  public: {
    Tables: {
      profiles: {
        Row: ProfileRow;
        Insert: Omit<ProfileRow, "created_at" | "updated_at"> & {
          locale?: string;
        };
        Update: Partial<ProfileRow>;
      };
      providers: {
        Row: ProviderRow;
        Insert: Pick<ProviderRow, "id" | "display_name"> & {
          status?: ProviderStatus;
          bg_check_status?: BgCheckStatus | null;
        };
        Update: Partial<ProviderRow>;
      };
    };
    Views: Record<string, never>;
    Functions: Record<string, never>;
    Enums: {
      user_role: UserRole;
      provider_status: ProviderStatus;
      bg_check_status: BgCheckStatus;
    };
  };
}

import "server-only";
import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";
import { type Database } from "@/lib/supabase/types";
import { supabaseAnonKey, supabaseUrl } from "@/lib/supabase/env";

/**
 * Server Supabase client bound to the request cookies (anon key, RLS-enforced).
 * Use in Server Components, Server Actions, and Route Handlers.
 */
export async function createClient() {
  const cookieStore = await cookies();

  return createServerClient<Database>(supabaseUrl(), supabaseAnonKey(), {
    cookies: {
      getAll() {
        return cookieStore.getAll();
      },
      setAll(cookiesToSet) {
        try {
          for (const { name, value, options } of cookiesToSet) {
            cookieStore.set(name, value, options);
          }
        } catch {
          // `setAll` called from a Server Component — safe to ignore; the
          // middleware refreshes the session cookie on each request.
        }
      },
    },
  });
}

