import * as React from "react";
import { t } from "@/lib/i18n";

export interface LogoProps {
  height?: number;
  /** "onPrimary" renders a light wordmark for use on the teal brand panel. */
  tone?: "default" | "onPrimary";
}

/**
 * Heard wordmark: concentric "listening" arcs (teal + amber) beside the name
 * set in the display serif. Ported from the design system's logo-heard.svg.
 */
export function Logo({ height = 40, tone = "default" }: LogoProps) {
  const onPrimary = tone === "onPrimary";
  const mark = onPrimary ? "#FFFFFF" : "#136F63";
  const ink = onPrimary ? "#FFFFFF" : "#2A2622";
  return (
    <svg
      height={height}
      viewBox="0 0 180 48"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      role="img"
      aria-label={t("app.name")}
    >
      <circle cx="20" cy="24" r="4.5" fill={mark} />
      <path
        d="M30 14a14 14 0 0 1 0 20"
        stroke={mark}
        strokeWidth="3.4"
        strokeLinecap="round"
        fill="none"
      />
      <path
        d="M37 8a23 23 0 0 1 0 32"
        stroke="#E08A3C"
        strokeWidth="3.4"
        strokeLinecap="round"
        fill="none"
      />
      <text
        x="56"
        y="33"
        fontFamily="Lora, Georgia, serif"
        fontSize="29"
        fontWeight="700"
        letterSpacing="-0.5"
        fill={ink}
      >
        Heard
      </text>
    </svg>
  );
}

