import * as React from "react";
import Link from "next/link";
import { Check } from "lucide-react";
import { Logo } from "@/components/shared/Logo";
import { Container } from "@/components/shared/Container";
import { t } from "@/lib/i18n";

const PANEL_POINTS = [
  "auth.panelPoint1",
  "auth.panelPoint2",
  "auth.panelPoint3",
] as const;

export default function AuthLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <Container
      as="main"
      id="main"
      className="flex flex-1 flex-col justify-center py-12 max-md:py-8"
    >
      {/* Desktop-first split: brand panel beside the form; stacks on mobile. */}
      <div className="grid grid-cols-[1.1fr_1fr] overflow-hidden rounded-lg border border-border bg-surface shadow-md max-md:grid-cols-1">
        <aside className="flex flex-col justify-between gap-10 bg-primary p-10 text-surface max-md:gap-8 max-md:p-8">
          <Link
            href="/"
            className="self-start rounded-sm"
            aria-label={`${t("app.name")}, ${t("nav.home").toLowerCase()}`}
          >
            <Logo height={40} tone="onPrimary" />
          </Link>
          <div className="flex flex-col gap-6">
            <h2 className="max-w-md text-h1 text-surface max-md:text-h2">
              {t("auth.panelHeading")}
            </h2>
            <ul className="flex flex-col gap-3">
              {PANEL_POINTS.map((key) => (
                <li key={key} className="flex items-start gap-3 text-lg">
                  <span
                    aria-hidden="true"
                    className="mt-1 grid size-6 flex-none place-items-center rounded-pill bg-surface/15"
                  >
                    <Check size={15} strokeWidth={2.5} />
                  </span>
                  {t(key)}
                </li>
              ))}
            </ul>
          </div>
          <p className="text-base text-surface/80 max-md:hidden">
            {t("shell.trustLine")}
          </p>
        </aside>

        <div className="flex flex-col justify-center p-10 max-md:p-8">
          {children}
        </div>
      </div>
    </Container>
  );
}

