-- =====================================================================
-- M1 — full data model (SPEC §4): expand providers and add availability,
-- bookings, sessions, payments, payouts, reviews, reports. Money is always
-- integer cents. RLS on every table.
-- =====================================================================

-- ---- Enums ----------------------------------------------------------
create type public.start_mode as enum ('now', 'scheduled');
create type public.booking_status as enum (
  'pending', 'confirmed', 'in_progress', 'completed', 'cancelled'
);
create type public.session_status as enum (
  'in_progress', 'completed', 'cancelled'
);
create type public.payment_status as enum (
  'authorized', 'captured', 'refunded', 'failed'
);
create type public.payout_status as enum ('scheduled', 'paid');
create type public.report_status as enum ('open', 'reviewed');

-- ---- providers: add profile + economics columns ---------------------
-- Defaults keep the sign-up trigger's minimal insert valid; onboarding and the
-- seed fill these in.
alter table public.providers
  add column bio                   text not null default '',
  add column voice_intro_path      text,
  add column avatar_color          text not null default '#5B8C7E',
  add column languages             text[] not null default '{}',
  add column topics                text[] not null default '{}',
  add column price_block_15_cents  integer not null default 0,
  add column price_block_30_cents  integer not null default 0,
  add column price_block_45_cents  integer not null default 0,
  add column overage_per_min_cents integer not null default 0,
  add column is_available_now      boolean not null default false,
  add column rating_avg            numeric(3, 2) not null default 0,
  add column rating_count          integer not null default 0,
  add column bg_check_ref          text,
  add column payout_account_ref    text;

alter table public.providers
  add constraint providers_prices_nonneg check (
    price_block_15_cents >= 0
    and price_block_30_cents >= 0
    and price_block_45_cents >= 0
    and overage_per_min_cents >= 0
  ),
  add constraint providers_rating_range check (
    rating_avg >= 0 and rating_avg <= 5 and rating_count >= 0
  );

-- ---- availability_slots --------------------------------------------
create table public.availability_slots (
  id          uuid primary key default gen_random_uuid(),
  provider_id uuid not null references public.providers (id) on delete cascade,
  start_at    timestamptz not null,
  end_at      timestamptz not null,
  is_booked   boolean not null default false,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint availability_time_order check (end_at > start_at)
);

-- ---- bookings -------------------------------------------------------
create table public.bookings (
  id                   uuid primary key default gen_random_uuid(),
  customer_id          uuid not null references public.profiles (id) on delete cascade,
  provider_id          uuid not null references public.providers (id) on delete cascade,
  slot_id              uuid references public.availability_slots (id) on delete set null,
  block_minutes        integer not null,
  start_mode           public.start_mode not null,
  scheduled_at         timestamptz,
  price_block_cents    integer not null,
  overage_per_min_cents integer not null default 0,
  status               public.booking_status not null default 'pending',
  payment_ref          text,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  constraint bookings_block_minutes check (block_minutes in (15, 30, 45)),
  constraint bookings_price_nonneg check (price_block_cents >= 0 and overage_per_min_cents >= 0),
  constraint bookings_scheduled_has_time check (
    start_mode = 'now' or scheduled_at is not null
  )
);

-- ---- sessions -------------------------------------------------------
create table public.sessions (
  id                     uuid primary key default gen_random_uuid(),
  booking_id             uuid not null references public.bookings (id) on delete cascade,
  provider_id            uuid not null references public.providers (id) on delete cascade,
  customer_id            uuid not null references public.profiles (id) on delete cascade,
  call_session_ref       text,
  started_at             timestamptz,
  ended_at               timestamptz,
  elapsed_seconds        integer not null default 0,
  block_minutes          integer not null,
  overage_minutes        integer not null default 0,
  total_price_cents      integer not null default 0,
  commission_cents       integer not null default 0,
  provider_earnings_cents integer not null default 0,
  status                 public.session_status not null default 'in_progress',
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now()
);

-- ---- payments (ledger) ----------------------------------------------
create table public.payments (
  id          uuid primary key default gen_random_uuid(),
  booking_id  uuid not null references public.bookings (id) on delete cascade,
  customer_id uuid not null references public.profiles (id) on delete cascade,
  amount_cents integer not null,
  status      public.payment_status not null,
  payment_ref text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- ---- payouts (weekly aggregation) -----------------------------------
create table public.payouts (
  id           uuid primary key default gen_random_uuid(),
  provider_id  uuid not null references public.providers (id) on delete cascade,
  period_start timestamptz not null,
  period_end   timestamptz not null,
  amount_cents integer not null,
  status       public.payout_status not null default 'scheduled',
  scheduled_for timestamptz,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

-- ---- reviews --------------------------------------------------------
-- session_id is nullable so seeded/display reviews can exist without a session.
create table public.reviews (
  id          uuid primary key default gen_random_uuid(),
  session_id  uuid references public.sessions (id) on delete set null,
  customer_id uuid not null references public.profiles (id) on delete cascade,
  provider_id uuid not null references public.providers (id) on delete cascade,
  rating      integer not null,
  comment     text,
  tip_cents   integer not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint reviews_rating_range check (rating between 1 and 5),
  constraint reviews_tip_nonneg check (tip_cents >= 0)
);

-- ---- reports (minimal safety hook; moderation UI deferred) -----------
create table public.reports (
  id          uuid primary key default gen_random_uuid(),
  reporter_id uuid not null references public.profiles (id) on delete cascade,
  target_id   uuid references public.profiles (id) on delete set null,
  session_id  uuid references public.sessions (id) on delete set null,
  reason      text not null,
  status      public.report_status not null default 'open',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- ---- updated_at triggers -------------------------------------------
create trigger availability_slots_set_updated_at before update on public.availability_slots
  for each row execute function public.set_updated_at();
create trigger bookings_set_updated_at before update on public.bookings
  for each row execute function public.set_updated_at();
create trigger sessions_set_updated_at before update on public.sessions
  for each row execute function public.set_updated_at();
create trigger payments_set_updated_at before update on public.payments
  for each row execute function public.set_updated_at();
create trigger payouts_set_updated_at before update on public.payouts
  for each row execute function public.set_updated_at();
create trigger reviews_set_updated_at before update on public.reviews
  for each row execute function public.set_updated_at();
create trigger reports_set_updated_at before update on public.reports
  for each row execute function public.set_updated_at();

-- ---- Indexes --------------------------------------------------------
create index providers_status_idx on public.providers (status);
create index providers_available_idx on public.providers (is_available_now);
create index providers_topics_idx on public.providers using gin (topics);
create index providers_languages_idx on public.providers using gin (languages);
create index availability_provider_idx on public.availability_slots (provider_id, start_at);
create index bookings_customer_idx on public.bookings (customer_id);
create index bookings_provider_idx on public.bookings (provider_id);
create index sessions_provider_idx on public.sessions (provider_id);
create index sessions_customer_idx on public.sessions (customer_id);
create index sessions_booking_idx on public.sessions (booking_id);
create index payments_customer_idx on public.payments (customer_id);
create index payments_booking_idx on public.payments (booking_id);
create index payouts_provider_idx on public.payouts (provider_id);
create index reviews_provider_idx on public.reviews (provider_id);
create index reports_reporter_idx on public.reports (reporter_id);

-- =====================================================================
-- Row-Level Security
-- Customers/providers touch only their own rows; public reads only approved
-- providers + their slots + reviews; admin sees all. Privileged writes
-- (payments, sessions, payouts) go through the service-role client in M2+.
-- =====================================================================

alter table public.availability_slots enable row level security;
alter table public.bookings enable row level security;
alter table public.sessions enable row level security;
alter table public.payments enable row level security;
alter table public.payouts enable row level security;
alter table public.reviews enable row level security;
alter table public.reports enable row level security;

-- availability_slots: public reads slots of approved providers; provider
-- manages own; admin all.
create policy "availability_select_public_or_own"
  on public.availability_slots for select
  using (
    exists (
      select 1 from public.providers p
      where p.id = availability_slots.provider_id
        and (p.status = 'approved' or p.id = auth.uid())
    )
    or public.is_admin()
  );
create policy "availability_write_own_or_admin"
  on public.availability_slots for all
  using (provider_id = auth.uid() or public.is_admin())
  with check (provider_id = auth.uid() or public.is_admin());

-- bookings: customer owns; provider sees bookings made with them; admin all.
create policy "bookings_select_party_or_admin"
  on public.bookings for select
  using (
    customer_id = auth.uid() or provider_id = auth.uid() or public.is_admin()
  );
create policy "bookings_insert_own"
  on public.bookings for insert
  with check (customer_id = auth.uid());
create policy "bookings_update_party_or_admin"
  on public.bookings for update
  using (customer_id = auth.uid() or provider_id = auth.uid() or public.is_admin())
  with check (customer_id = auth.uid() or provider_id = auth.uid() or public.is_admin());

-- sessions: either party reads; admin all. Writes are server-side (service role).
create policy "sessions_select_party_or_admin"
  on public.sessions for select
  using (
    customer_id = auth.uid() or provider_id = auth.uid() or public.is_admin()
  );

-- payments: customer reads own; admin all. Writes via service role.
create policy "payments_select_own_or_admin"
  on public.payments for select
  using (customer_id = auth.uid() or public.is_admin());

-- payouts: provider reads own; admin all. Writes via service role.
create policy "payouts_select_own_or_admin"
  on public.payouts for select
  using (provider_id = auth.uid() or public.is_admin());

-- reviews: public read (shown on profiles); customer writes own; admin all.
create policy "reviews_select_all"
  on public.reviews for select
  using (true);
create policy "reviews_insert_own"
  on public.reviews for insert
  with check (customer_id = auth.uid());
create policy "reviews_update_own_or_admin"
  on public.reviews for update
  using (customer_id = auth.uid() or public.is_admin())
  with check (customer_id = auth.uid() or public.is_admin());

-- reports: reporter inserts and reads own; admin all (moderation UI deferred).
create policy "reports_insert_own"
  on public.reports for insert
  with check (reporter_id = auth.uid());
create policy "reports_select_own_or_admin"
  on public.reports for select
  using (reporter_id = auth.uid() or public.is_admin());

