/**
 * Single import surface for database types. `Database` is generated from the
 * live schema (`supabase gen types typescript --local` → database.types.ts);
 * regenerate it whenever a migration changes the schema. The named aliases
 * below are derived from it so the rest of the app imports stable names.
 */
export type { Database };

export type UserRole = Database["public"]["Enums"]["user_role"];
export type ProviderStatus = Database["public"]["Enums"]["provider_status"];
export type BgCheckStatus = Database["public"]["Enums"]["bg_check_status"];
