  fullName: z
    .string()
    .trim()
    .min(1, "Enter your name.")
    .max(120, "That name is too long."),
  email: emailSchema,
  password: passwordSchema,
  role: roleSchema,
});
export type SignUpInput = z.infer<typeof signUpSchema>;

/* ===================================================================
   Entity schemas (M1). Shared by the server actions built in M3–M7.
   Money is integer cents; block lengths are fixed at 15 / 30 / 45.
   =================================================================== */

export const BLOCK_MINUTES = [15, 30, 45] as const;
export const blockMinutesSchema = z
  .number()
  .int()
  .refine((n): n is 15 | 30 | 45 => (BLOCK_MINUTES as readonly number[]).includes(n), {
    message: "Choose a 15, 30, or 45-minute block.",
  });

const centsSchema = z
  .number()
  .int("Use whole cents.")
  .min(0, "Cannot be negative.");

/** Provider onboarding / profile edit (CLAUDE.md: prices in integer cents). */
export const providerOnboardingSchema = z.object({
  displayName: z.string().trim().min(1, "Add a display name.").max(60),
  bio: z.string().trim().max(800, "Keep your bio under 800 characters.").default(""),
  voiceIntroPath: z.string().trim().min(1, "Record a voice intro.").optional(),
  languages: z.array(z.string().trim().min(1)).min(1, "Pick at least one language."),
  topics: z.array(z.string().trim().min(1)).min(1, "Pick at least one topic."),
  priceBlock15Cents: centsSchema,
  priceBlock30Cents: centsSchema,
  priceBlock45Cents: centsSchema,
  overagePerMinCents: centsSchema,
});
export type ProviderOnboardingInput = z.infer<typeof providerOnboardingSchema>;

/** Provider "Available now" toggle. */
export const availabilityToggleSchema = z.object({
  isAvailableNow: z.boolean(),
});

/** A scheduled availability slot. */
export const availabilitySlotSchema = z
  .object({
    startAt: z.string().datetime({ message: "Invalid start time." }),
    endAt: z.string().datetime({ message: "Invalid end time." }),
  })
  .refine((s) => new Date(s.endAt) > new Date(s.startAt), {
    message: "The slot must end after it starts.",
    path: ["endAt"],
  });

/** Booking creation (customer side). */
export const bookingCreateSchema = z
  .object({
    providerId: z.string().uuid(),
    blockMinutes: blockMinutesSchema,
    startMode: z.enum(["now", "scheduled"]),
    scheduledAt: z.string().datetime().optional(),
    slotId: z.string().uuid().optional(),
  })
  .refine((b) => b.startMode === "now" || !!b.scheduledAt, {
    message: "Choose a time for your scheduled session.",
    path: ["scheduledAt"],
  });
export type BookingCreateInput = z.infer<typeof bookingCreateSchema>;

/** Post-session review + optional tip (no commission on tips). */
export const reviewSchema = z.object({
  sessionId: z.string().uuid(),
  providerId: z.string().uuid(),
  rating: z.number().int().min(1, "Choose a rating.").max(5),
  comment: z.string().trim().max(1000).optional(),
  tipCents: centsSchema.default(0),
});
export type ReviewInput = z.infer<typeof reviewSchema>;

/** Minimal "Report a problem" safety hook (moderation UI deferred). */
export const reportSchema = z.object({
  targetId: z.string().uuid().optional(),
  sessionId: z.string().uuid().optional(),
  reason: z.string().trim().min(1, "Tell us what happened.").max(2000),
});
export type ReportInput = z.infer<typeof reportSchema>;

/** Browse / discovery filters. */
export const browseFiltersSchema = z.object({
  topic: z.string().trim().min(1).optional(),
  language: z.string().trim().min(1).optional(),
  availableNow: z.boolean().optional(),
  maxPriceCents: centsSchema.optional(),
});
export type BrowseFilters = z.infer<typeof browseFiltersSchema>;

/** Admin provider-approval decision. */
export const providerDecisionSchema = z.object({
  providerId: z.string().uuid(),
  decision: z.enum(["approve", "reject", "suspend"]),
});
export type ProviderDecision = z.infer<typeof providerDecisionSchema>;

