"use client";

import * as React from "react";
import { useRouter } from "next/navigation";
import { ChevronLeft, ChevronRight, CircleCheck, CircleAlert, Phone } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Field, Input } from "@/components/ui/Field";
import { Chip } from "@/components/ui/Chip";
import { VoiceIntroRecorder } from "@/components/provider/VoiceIntroRecorder";
import { TOPICS, LANGUAGES } from "@/lib/constants";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";
import { completeOnboarding } from "@/app/(provider)/provider/actions";

export interface OnboardingInitial {
  displayName: string;
  bio: string;
  voiceIntroPath: string | null;
  languages: string[];
  topics: string[];
  price15: string;
  price30: string;
  price45: string;
  overage: string;
  isAvailableNow: boolean;
}

const TOTAL_STEPS = 4;

function dollarsToCents(value: string): number {
  const n = Number(value);
  return Number.isFinite(n) && n >= 0 ? Math.round(n * 100) : 0;
}

export function OnboardingFlow({
  providerId,
  initial,
}: {
  providerId: string;
  initial: OnboardingInitial;
}) {
  const router = useRouter();
  const { announce } = useToast();
  const [step, setStep] = React.useState(1);
  const [submitting, setSubmitting] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  const [displayName, setDisplayName] = React.useState(initial.displayName);
  const [bio, setBio] = React.useState(initial.bio);
  const [voiceIntroPath, setVoiceIntroPath] = React.useState(initial.voiceIntroPath);
  const [topics, setTopics] = React.useState<string[]>(initial.topics);
  const [languages, setLanguages] = React.useState<string[]>(initial.languages);
  const [price15, setPrice15] = React.useState(initial.price15);
  const [price30, setPrice30] = React.useState(initial.price30);
  const [price45, setPrice45] = React.useState(initial.price45);
  const [overage, setOverage] = React.useState(initial.overage);
  const [isAvailableNow, setIsAvailableNow] = React.useState(initial.isAvailableNow);

  const headingRef = React.useRef<HTMLHeadingElement | null>(null);
  React.useEffect(() => {
    headingRef.current?.focus();
  }, [step]);

  function toggle(list: string[], value: string): string[] {
    return list.includes(value)
      ? list.filter((v) => v !== value)
      : [...list, value];
  }

  function goNext() {
    if (step < TOTAL_STEPS) {
      setStep(step + 1);
      announce(t("provider.stepOf", { current: step + 1, total: TOTAL_STEPS }));
    }
  }
  function goBack() {
    if (step > 1) {
      setStep(step - 1);
      announce(t("provider.stepOf", { current: step - 1, total: TOTAL_STEPS }));
    }
  }

  async function onSubmit() {
    setSubmitting(true);
    setError(null);
    const res = await completeOnboarding({
      displayName,
      bio,
      voiceIntroPath: voiceIntroPath ?? undefined,
      languages,
      topics,
      priceBlock15Cents: dollarsToCents(price15),
      priceBlock30Cents: dollarsToCents(price30),
      priceBlock45Cents: dollarsToCents(price45),
      overagePerMinCents: dollarsToCents(overage),
      isAvailableNow,
    });
    // On success the action redirects; only an error returns here.
    if (res?.error) {
      setError(res.error);
      setSubmitting(false);
    } else {
      router.push("/provider/dashboard?onboarded=1");
    }
  }

  const done = {
    voice: bio.trim().length > 0,
    topics: topics.length > 0 && languages.length > 0,
    pricing:
      dollarsToCents(price15) > 0 &&
      dollarsToCents(price30) > 0 &&
      dollarsToCents(price45) > 0,
  };

  return (
    <div className="flex flex-col gap-6">
      <p className="text-base font-bold text-ink-soft" aria-live="polite">
        {t("provider.stepOf", { current: step, total: TOTAL_STEPS })}
      </p>

      {error ? (
        <p
          role="alert"
          className="flex items-start gap-2 rounded-card border-l-4 border-alert bg-alert-tint px-4 py-3 text-base"
        >
          <CircleAlert size={20} aria-hidden="true" className="mt-0.5 text-alert" />
          {error}
        </p>
      ) : null}

      {step === 1 ? (
        <section className="flex flex-col gap-5">
          <div>
            <h2 ref={headingRef} tabIndex={-1} className="text-h2 outline-none">
              {t("provider.step1Title")}
            </h2>
            <p className="mt-1 text-lg text-ink-soft">{t("provider.step1Help")}</p>
          </div>
          <Field label={t("auth.fullNameLabel")} required>
            {(p) => (
              <Input
                {...p}
                value={displayName}
                onChange={(e) => setDisplayName(e.target.value)}
                maxLength={60}
              />
            )}
          </Field>
          <VoiceIntroRecorder
            providerId={providerId}
            initialPath={voiceIntroPath}
            onUploaded={setVoiceIntroPath}
          />
          <Field
            label={t("provider.introTextLabel")}
            hint={t("provider.introTextHint")}
            required
          >
            {(p) => (
              <textarea
                {...p}
                value={bio}
                onChange={(e) => setBio(e.target.value)}
                rows={4}
                maxLength={800}
                placeholder={t("provider.introTextPlaceholder")}
                className="rounded-btn border border-border-strong bg-surface px-3.5 py-2.5 text-base text-ink placeholder:text-ink-faint"
              />
            )}
          </Field>
        </section>
      ) : null}

      {step === 2 ? (
        <section className="flex flex-col gap-5">
          <div>
            <h2 ref={headingRef} tabIndex={-1} className="text-h2 outline-none">
              {t("provider.step2Title")}
            </h2>
            <p className="mt-1 text-lg text-ink-soft">{t("provider.step2Help")}</p>
          </div>
          <fieldset className="flex flex-col gap-3">
            <legend className="text-base font-bold text-ink">
              {t("provider.topicsLabel")}
            </legend>
            <div className="flex flex-wrap gap-2.5">
              {TOPICS.map((topic) => (
                <Chip
                  key={topic}
                  selected={topics.includes(topic)}
                  onClick={() => setTopics(toggle(topics, topic))}
                >
                  {topic}
                </Chip>
              ))}
            </div>
          </fieldset>
          <fieldset className="flex flex-col gap-3">
            <legend className="text-base font-bold text-ink">
              {t("provider.languagesLabel")}
            </legend>
            <div className="flex flex-wrap gap-2.5">
              {LANGUAGES.map((lang) => (
                <Chip
                  key={lang}
                  selected={languages.includes(lang)}
                  onClick={() => setLanguages(toggle(languages, lang))}
                >
                  {lang}
                </Chip>
              ))}
            </div>
          </fieldset>
        </section>
      ) : null}

      {step === 3 ? (
        <section className="flex flex-col gap-5">
          <div>
            <h2 ref={headingRef} tabIndex={-1} className="text-h2 outline-none">
              {t("provider.step3Title")}
            </h2>
            <p className="mt-1 text-lg text-ink-soft">{t("provider.step3Help")}</p>
          </div>
          <div className="grid grid-cols-2 gap-4 max-sm:grid-cols-1">
            {(
              [
                ["provider.price15Label", price15, setPrice15],
                ["provider.price30Label", price30, setPrice30],
                ["provider.price45Label", price45, setPrice45],
                ["provider.overageLabel", overage, setOverage],
              ] as const
            ).map(([labelKey, value, setter]) => (
              <Field
                key={labelKey}
                label={t(labelKey)}
                hint={t("provider.dollarsHint")}
              >
                {(p) => (
                  <Input
                    {...p}
                    type="number"
                    inputMode="decimal"
                    min={0}
                    step="0.01"
                    value={value}
                    onChange={(e) => setter(e.target.value)}
                  />
                )}
              </Field>
            ))}
          </div>
          <label className="flex items-center gap-3 rounded-card border border-border bg-surface p-4 text-base font-bold text-ink">
            <input
              type="checkbox"
              checked={isAvailableNow}
              onChange={(e) => setIsAvailableNow(e.target.checked)}
              className="size-5"
            />
            {t("provider.availableNowLabel")}
          </label>
        </section>
      ) : null}

      {step === 4 ? (
        <section className="flex flex-col gap-5">
          <div>
            <h2 ref={headingRef} tabIndex={-1} className="text-h2 outline-none">
              {t("provider.step4Title")}
            </h2>
            <p className="mt-1 text-lg text-ink-soft">{t("provider.step4Help")}</p>
          </div>
          <ul className="flex flex-col gap-2">
            {(
              [
                ["provider.verifyVoice", done.voice],
                ["provider.verifyTopics", done.topics],
                ["provider.verifyPricing", done.pricing],
              ] as const
            ).map(([labelKey, ok]) => (
              <li
                key={labelKey}
                className="flex items-center justify-between rounded-card border border-border bg-surface px-4 py-3 text-base"
              >
                <span className="font-bold text-ink">{t(labelKey)}</span>
                <span
                  className={`inline-flex items-center gap-1.5 font-bold ${ok ? "text-success" : "text-ink-soft"}`}
                >
                  {ok ? (
                    <CircleCheck size={18} aria-hidden="true" />
                  ) : (
                    <CircleAlert size={18} aria-hidden="true" />
                  )}
                  {ok ? t("provider.verifyDone") : t("provider.verifyMissing")}
                </span>
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      <div className="flex items-center justify-between gap-3 border-t border-border pt-5">
        <Button
          variant="ghost"
          icon={ChevronLeft}
          onClick={goBack}
          disabled={step === 1}
        >
          {t("provider.back")}
        </Button>
        {step < TOTAL_STEPS ? (
          <Button icon={ChevronRight} onClick={goNext}>
            {t("provider.next")}
          </Button>
        ) : (
          <Button
            onClick={onSubmit}
            disabled={submitting || !done.voice || !done.topics || !done.pricing}
          >
            {submitting ? t("ui.loading") : t("provider.finish")}
          </Button>
        )}
      </div>

      <p className="flex items-center gap-2 text-base text-ink-soft">
        <Phone size={18} strokeWidth={2} aria-hidden="true" />
        {t("provider.needHelp")}
      </p>
    </div>
  );
}

