  return (
    <div className="flex flex-col gap-6">
      <h1 className="text-h1">{t("provider.onboardingTitle")}</h1>
      <Card className="p-6 sm:p-8">
        <OnboardingFlow providerId={profile.id} initial={initial} />
      </Card>
    </div>
  );
}

