"use client";

import * as React from "react";
import { useTransition } from "react";
import { CircleCheck, Moon } from "lucide-react";
import { setAvailability } from "@/app/(provider)/provider/actions";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";

/**
 * Large, unmistakable "Available now" switch. State is conveyed by an icon and
 * a text label (never colour alone), announced on change, and operable by
 * keyboard via the underlying role="switch".
 */
export function AvailabilityToggle({
  initial,
  disabled,
}: {
  initial: boolean;
  disabled?: boolean;
}) {
  const [on, setOn] = React.useState(initial);
  const [pending, startTransition] = useTransition();
  const { announce } = useToast();

  function flip() {
    const next = !on;
    setOn(next);
    announce(next ? t("provider.available") : t("provider.offline"), true);
    startTransition(async () => {
      const res = await setAvailability(next);
      if (!res.ok) setOn(!next); // revert on failure
    });
  }

  if (disabled) {
    return (
      <p className="rounded-card border border-border bg-surface-sunk px-4 py-3 text-base text-ink-soft">
        {t("provider.availableNotApproved")}
      </p>
    );
  }

  return (
    <div className="flex flex-col gap-3">
      <button
        type="button"
        role="switch"
        aria-checked={on}
        onClick={flip}
        disabled={pending}
        className={[
          "flex min-h-12 w-full items-center justify-between gap-3 rounded-card border-2 px-5 py-4 text-left text-lg font-bold transition-colors",
          on
            ? "border-success bg-success-tint text-success"
            : "border-border-strong bg-surface text-ink",
        ].join(" ")}
      >
        <span className="flex items-center gap-2.5">
          {on ? (
            <CircleCheck size={24} strokeWidth={2} aria-hidden="true" />
          ) : (
            <Moon size={24} strokeWidth={2} aria-hidden="true" />
          )}
          {on ? t("provider.available") : t("provider.offline")}
        </span>
        <span className="text-base font-bold text-ink-soft">
          {on ? t("provider.turnOff") : t("provider.turnOn")}
        </span>
      </button>
    </div>
  );
}

