(() => {
  const want = ['everyday chat','books','English'];
  const btns = [...document.querySelectorAll('button')];
  const clicked = [];
  for (const w of want) {
    const b = btns.find(x => x.textContent.trim() === w);
    if (b) { b.click(); clicked.push(w); }
  }
  return clicked;
})()

(() => {
  function setNative(el, value){
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value').set;
    setter.call(el, value);
    el.dispatchEvent(new Event('input',{bubbles:true}));
  }
  const nums = [...document.querySelectorAll('input[type=number]')];
  const vals = ['12','24','36','0.80'];
  nums.forEach((el,i)=> { if (vals[i]!==undefined) setNative(el, vals[i]); });
  // also tick the availability checkbox
  const cb = document.querySelector('input[type=checkbox]');
  if (cb && !cb.checked) { cb.click(); }
  return { filled: nums.length, available: cb?.checked };
})()

