import { describe, it, expect, vi } from "vitest";
import { screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { axe } from "jest-axe";
import { renderWithProviders } from "./helpers";

// Provider components import "use server" actions that pull in server-only
// modules; mock them so the components render in jsdom.
vi.mock("@/app/(provider)/provider/actions", () => ({
  completeOnboarding: vi.fn(async () => ({ ok: true })),
  setAvailability: vi.fn(async () => ({ ok: true })),
}));
vi.mock("next/navigation", () => ({
  useRouter: () => ({ push: vi.fn() }),
}));

import { AvailabilityToggle } from "@/components/provider/AvailabilityToggle";
import { OnboardingFlow } from "@/components/provider/OnboardingFlow";

const INITIAL = {
  displayName: "Nadia",
  bio: "",
  voiceIntroPath: null,
  languages: [],
  topics: [],
  price15: "",
  price30: "",
  price45: "",
  overage: "",
  isAvailableNow: false,
};

describe("AvailabilityToggle", () => {
  it("exposes a switch with aria-checked and a text label (not colour alone)", async () => {
    const { container } = renderWithProviders(
      <AvailabilityToggle initial={false} />,
    );
    const sw = screen.getByRole("switch");
    expect(sw).toHaveAttribute("aria-checked", "false");
    expect(sw).toHaveTextContent(/you're offline/i);
    expect(await axe(container)).toHaveNoViolations();
  });

  it("flips state on click", async () => {
    const user = userEvent.setup();
    renderWithProviders(<AvailabilityToggle initial={false} />);
    await user.click(screen.getByRole("switch"));
    expect(screen.getByRole("switch")).toHaveAttribute("aria-checked", "true");
  });

  it("shows the locked message when not yet approved", () => {
    renderWithProviders(<AvailabilityToggle initial={false} disabled />);
    expect(screen.queryByRole("switch")).not.toBeInTheDocument();
    expect(screen.getByText(/once your profile is approved/i)).toBeInTheDocument();
  });
});

describe("OnboardingFlow", () => {
  it("renders step 1 of 4 with labelled controls and no a11y violations", async () => {
    const { container } = renderWithProviders(
      <OnboardingFlow providerId="p1" initial={INITIAL} />,
    );
    expect(screen.getByText("Step 1 of 4")).toBeInTheDocument();
    expect(
      screen.getByRole("heading", { name: /record your voice intro/i }),
    ).toBeInTheDocument();
    expect(screen.getByText(/a short written intro/i)).toBeInTheDocument();
    expect(await axe(container)).toHaveNoViolations();
  });

  it("advances to the topics step", async () => {
    const user = userEvent.setup();
    renderWithProviders(<OnboardingFlow providerId="p1" initial={INITIAL} />);
    await user.click(screen.getByRole("button", { name: /next/i }));
    expect(
      screen.getByRole("heading", { name: /what do you enjoy talking about/i }),
    ).toBeInTheDocument();
  });
});

