"use client";

import * as React from "react";
import { useTransition } from "react";
import { Check, X, Ban } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Tag } from "@/components/ui/Tag";
import { Avatar } from "@/components/ui/Avatar";
import { VoicePlayer } from "@/components/ui/VoicePlayer";
import { decideProvider } from "@/app/(admin)/admin/actions";
import { formatBlockPrice, formatRating } from "@/lib/format";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";
import { type ProviderRow } from "@/lib/supabase/types";

type Decision = "approve" | "reject" | "suspend";

const STATUS_LABEL: Record<ProviderRow["status"], string> = {
  approved: t("admin.statusApproved"),
  pending: t("admin.statusPending"),
  rejected: t("admin.statusRejected"),
  suspended: t("admin.statusSuspended"),
};

export function ProviderApprovalCard({
  provider,
  audioUrl,
}: {
  provider: ProviderRow;
  audioUrl: string | null;
}) {
  const [pending, startTransition] = useTransition();
  const { announce, toast } = useToast();

  function decide(decision: Decision) {
    startTransition(async () => {
      const res = await decideProvider({ providerId: provider.id, decision });
      if (!res.ok) {
        toast(t("admin.decisionError"), "alert");
        return;
      }
      const key =
        decision === "approve"
          ? "admin.approvedAnnounce"
          : decision === "reject"
            ? "admin.rejectedAnnounce"
            : "admin.suspendedAnnounce";
      announce(t(key, { name: provider.display_name }), true);
    });
  }

  return (
    <Card as="li" className="flex flex-col gap-4">
      <div className="flex items-start gap-3">
        <Avatar name={provider.display_name} color={provider.avatar_color} />
        <div className="flex-1">
          <h3 className="text-h3">{provider.display_name}</h3>
          <p className="text-sm font-bold text-ink-soft">
            {STATUS_LABEL[provider.status]} ·{" "}
            {t("admin.bgCheckLabel")}: {provider.bg_check_status}
            {provider.rating_count > 0
              ? ` · ${formatRating(provider.rating_avg)} (${provider.rating_count})`
              : ""}
          </p>
        </div>
      </div>

      <VoicePlayer name={provider.display_name} intro={provider.bio} big audioUrl={audioUrl} />

      <dl className="flex flex-col gap-2 text-base">
        <div className="flex flex-wrap items-center gap-2">
          <dt className="font-bold text-ink-soft">{t("admin.topicsLabel")}:</dt>
          {provider.topics.map((topic) => (
            <dd key={topic}>
              <Tag>{topic}</Tag>
            </dd>
          ))}
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <dt className="font-bold text-ink-soft">
            {t("admin.languagesLabel")}:
          </dt>
          <dd className="text-ink">{provider.languages.join(", ")}</dd>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <dt className="font-bold text-ink-soft">{t("admin.pricesLabel")}:</dt>
          <dd className="text-ink">
            {formatBlockPrice(provider.price_block_15_cents, 15)} ·{" "}
            {formatBlockPrice(provider.price_block_30_cents, 30)} ·{" "}
            {formatBlockPrice(provider.price_block_45_cents, 45)}
          </dd>
        </div>
      </dl>

      <div className="flex flex-wrap gap-3 border-t border-border pt-4">
        {provider.status !== "approved" ? (
          <Button icon={Check} onClick={() => decide("approve")} disabled={pending}>
            {t("admin.approve")}
          </Button>
        ) : null}
        {provider.status !== "suspended" && provider.status !== "rejected" ? (
          <Button
            variant="ghost"
            icon={Ban}
            onClick={() => decide("suspend")}
            disabled={pending}
          >
            {t("admin.suspend")}
          </Button>
        ) : null}
        {provider.status === "pending" ? (
          <Button
            variant="danger"
            icon={X}
            onClick={() => decide("reject")}
            disabled={pending}
          >
            {t("admin.reject")}
          </Button>
        ) : null}
      </div>
    </Card>
  );
}

