import { describe, it, expect, vi } from "vitest";
import { screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { axe } from "jest-axe";
import { renderWithProviders } from "./helpers";
import { type ProviderRow } from "@/lib/supabase/types";

const decideProvider = vi.fn(async () => ({ ok: true }));
vi.mock("@/app/(admin)/admin/actions", () => ({
  decideProvider: (...args: unknown[]) => decideProvider(...(args as [])),
}));

import { ProviderApprovalCard } from "@/components/admin/ProviderApprovalCard";

const PENDING: ProviderRow = {
  id: "00000000-0000-0000-0000-000000000099",
  display_name: "Nadia",
  bio: "Hi, I'm Nadia. I love calm conversations.",
  voice_intro_path: null,
  avatar_color: "#5B8C7E",
  status: "pending",
  bg_check_status: "pending",
  bg_check_ref: null,
  languages: ["English"],
  topics: ["books"],
  price_block_15_cents: 1200,
  price_block_30_cents: 2400,
  price_block_45_cents: 3600,
  overage_per_min_cents: 80,
  is_available_now: false,
  rating_avg: 0,
  rating_count: 0,
  payout_account_ref: null,
  created_at: "2026-06-05T00:00:00.000Z",
  updated_at: "2026-06-05T00:00:00.000Z",
};

describe("ProviderApprovalCard", () => {
  it("shows pending details and approve/reject/suspend, no a11y violations", async () => {
    const { container } = renderWithProviders(
      <ProviderApprovalCard provider={PENDING} audioUrl={null} />,
    );
    expect(screen.getByRole("heading", { name: "Nadia" })).toBeInTheDocument();
    expect(screen.getByRole("button", { name: /approve/i })).toBeInTheDocument();
    expect(screen.getByRole("button", { name: /reject/i })).toBeInTheDocument();
    expect(screen.getByRole("button", { name: /suspend/i })).toBeInTheDocument();
    // voice intro transcript is shown
    expect(screen.getByText(/i love calm conversations/i)).toBeInTheDocument();
    expect(await axe(container)).toHaveNoViolations();
  });

  it("calls decideProvider(approve) on Approve", async () => {
    const user = userEvent.setup();
    renderWithProviders(<ProviderApprovalCard provider={PENDING} audioUrl={null} />);
    await user.click(screen.getByRole("button", { name: /approve/i }));
    expect(decideProvider).toHaveBeenCalledWith({
      providerId: PENDING.id,
      decision: "approve",
    });
  });

  it("an approved provider offers only Suspend", () => {
    renderWithProviders(
      <ProviderApprovalCard
        provider={{ ...PENDING, status: "approved", bg_check_status: "clear" }}
        audioUrl={null}
      />,
    );
    expect(screen.queryByRole("button", { name: /approve/i })).not.toBeInTheDocument();
    expect(screen.queryByRole("button", { name: /reject/i })).not.toBeInTheDocument();
    expect(screen.getByRole("button", { name: /suspend/i })).toBeInTheDocument();
  });
});

