      <Card className="p-6 sm:p-8">
        <BookingForm
          defaultMode={mode === "scheduled" ? "scheduled" : "now"}
          provider={{
            id: provider.id,
            displayName: provider.display_name,
            prices: {
              15: provider.price_block_15_cents,
              30: provider.price_block_30_cents,
              45: provider.price_block_45_cents,
            },
            overagePerMinCents: provider.overage_per_min_cents,
          }}
        />
      </Card>
    </div>
  );
}

