import { describe, it, expect, vi } from "vitest";
import { screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { axe } from "jest-axe";
import { renderWithProviders } from "./helpers";
import { type PublicProvider } from "@/lib/supabase/types";

const createBooking = vi.fn(async () => ({}));
vi.mock("@/app/(customer)/actions", () => ({
  createBooking: (...args: unknown[]) => createBooking(...(args as [])),
}));

import { BookingForm } from "@/components/customer/BookingForm";
import { ListenerCard } from "@/components/customer/ListenerCard";

const PROVIDER = {
  id: "00000000-0000-0000-0000-000000000001",
  displayName: "Maya",
  prices: { 15: 1200, 30: 2400, 45: 3600 } as Record<15 | 30 | 45, number>,
  overagePerMinCents: 80,
};

const PUBLIC_PROVIDER: PublicProvider = {
  id: PROVIDER.id,
  display_name: "Maya",
  bio: "I love a slow, wandering conversation.",
  voice_intro_path: null,
  avatar_color: "#5B8C7E",
  status: "approved",
  bg_check_status: "clear",
  languages: ["English", "Spanish"],
  topics: ["everyday chat", "grief", "books"],
  price_block_15_cents: 1200,
  price_block_30_cents: 2400,
  price_block_45_cents: 3600,
  overage_per_min_cents: 80,
  is_available_now: true,
  rating_avg: 4.9,
  rating_count: 128,
  created_at: "2026-06-05T00:00:00.000Z",
  updated_at: "2026-06-05T00:00:00.000Z",
};

describe("BookingForm", () => {
  it("defaults to a 30-min now booking with a $24 summary, no a11y violations", async () => {
    const { container } = renderWithProviders(
      <BookingForm provider={PROVIDER} defaultMode="now" />,
    );
    expect(screen.getByText("Due now")).toBeInTheDocument();
    // $24 appears for the selected block + total
    expect(screen.getAllByText("$24").length).toBeGreaterThan(0);
    expect(await axe(container)).toHaveNoViolations();
  });

  it("submits the chosen block and mode", async () => {
    const user = userEvent.setup();
    renderWithProviders(<BookingForm provider={PROVIDER} defaultMode="now" />);
    await user.click(screen.getByRole("button", { name: /confirm & connect/i }));
    expect(createBooking).toHaveBeenCalledWith({
      providerId: PROVIDER.id,
      blockMinutes: 30,
      startMode: "now",
      scheduledAt: undefined,
    });
  });
});

describe("ListenerCard", () => {
  it("shows name, price and a profile link with no a11y violations", async () => {
    const { container } = renderWithProviders(
      <ul>
        <ListenerCard provider={PUBLIC_PROVIDER} audioUrl={null} />
      </ul>,
    );
    expect(screen.getByRole("heading", { name: "Maya" })).toBeInTheDocument();
    expect(screen.getByText("$24 / 30 min")).toBeInTheDocument();
    expect(
      screen.getByRole("link", { name: /view maya's profile/i }),
    ).toHaveAttribute("href", `/listeners/${PROVIDER.id}`);
    expect(screen.getByText("Available now")).toBeInTheDocument();
    expect(await axe(container)).toHaveNoViolations();
  });
});

