import { getBooking, getSessionByBooking } from "@/lib/db/queries";
import { formatCents } from "@/lib/format";
import { t } from "@/lib/i18n";

function fmtDuration(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}:${String(s).padStart(2, "0")}`;
}

export default async function ProviderSessionSummaryPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const profile = await requireRole("provider");
  const { id } = await params;
  const [booking, session] = await Promise.all([
    getBooking(id),
    getSessionByBooking(id),
  ]);
  if (!booking || booking.provider_id !== profile.id || !session) notFound();

  return (
    <div className="mx-auto flex w-full max-w-xl flex-col gap-6">
      <div className="flex items-center gap-3">
        <CircleCheck size={28} aria-hidden="true" className="text-success" />
        <h1 className="text-h1">{t("session.providerSummaryTitle")}</h1>
      </div>

      <Card as="section" className="flex flex-col gap-3">
        <div className="flex items-center justify-between text-base">
          <span className="text-ink-soft">{t("session.providerDuration")}</span>
          <span className="font-bold text-ink">
            {fmtDuration(session.elapsed_seconds)}
          </span>
        </div>
        <div className="flex items-center justify-between border-t border-border pt-3 text-lg">
          <span className="font-bold text-ink">{t("session.providerEarned")}</span>
          <span className="font-bold text-ink">
            {formatCents(session.provider_earnings_cents)}
          </span>
        </div>
      </Card>

      <Link href="/provider/dashboard" className="rounded-btn self-start">
        <Button>{t("session.backToDashboard")}</Button>
      </Link>
    </div>
  );
}

