import Link from "next/link";
import { CircleCheck } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { requireRole } from "@/lib/auth";
import { listCustomerBookings } from "@/lib/db/queries";
import { formatCents } from "@/lib/format";
import { t, type MessageKey } from "@/lib/i18n";
import { type BookingRow } from "@/lib/supabase/types";

export const metadata = { title: `${t("account.title")} · ${t("app.name")}` };

const STATUS_KEY: Record<BookingRow["status"], MessageKey> = {
  pending: "account.statusPending",
  confirmed: "account.statusConfirmed",
  in_progress: "account.statusInProgress",
  completed: "account.statusCompleted",
  cancelled: "account.statusCancelled",
};

export default async function AccountPage({
  searchParams,
}: {
  searchParams: Promise<{ booked?: string }>;
}) {
  const profile = await requireRole("customer");
  const { booked } = await searchParams;
  const bookings = await listCustomerBookings(profile.id);

  return (
    <div className="flex flex-col gap-6">
      <div className="flex flex-col gap-1.5">
        <h1 className="text-h1">{t("account.title")}</h1>
        <p className="text-lg text-ink-soft">{t("account.subtitle")}</p>
      </div>

      {booked ? (
        <Card className="flex items-center gap-3 border-l-4 border-success bg-success-tint">
          <CircleCheck size={22} aria-hidden="true" className="text-success" />
          <p className="text-base font-bold text-ink">
            {t("account.bookedConfirmed")}
          </p>
        </Card>
      ) : null}

      {bookings.length === 0 ? (
        <Card className="flex flex-col items-start gap-3">
          <p className="text-base text-ink-soft">{t("account.none")}</p>
          <Link href="/browse" className="rounded-btn">
            <Button>{t("account.findListener")}</Button>
          </Link>
        </Card>
      ) : (
        <ul className="flex flex-col gap-3">
          {bookings.map((b) => (
            <Card as="li" key={b.id} className="flex flex-wrap items-center justify-between gap-3">
              <div>
                <p className="text-base font-bold text-ink">
                  {t("account.withProvider", { minutes: b.block_minutes })}
                </p>
                <p className="text-sm font-bold text-ink-soft">
                  {t(STATUS_KEY[b.status])}
                </p>
              </div>
              <div className="flex items-center gap-4">
                <span className="text-base font-bold text-ink">
                  {formatCents(b.price_block_cents)}
                </span>
                {b.status === "confirmed" || b.status === "in_progress" ? (
                  <Link href={`/session/${b.id}`} className="rounded-btn">
                    <Button>{t("session.join")}</Button>
                  </Link>
                ) : null}
                {b.status === "completed" ? (
                  <Link
                    href={`/session/${b.id}/summary`}
                    className="rounded-btn text-base font-bold text-primary underline underline-offset-[3px]"
                  >
                    {t("summary.receiptHeading")}
                  </Link>
                ) : null}
              </div>
            </Card>
          ))}
        </ul>
      )}
    </div>
  );
}

