import { describe, it, expect, vi } from "vitest";
import { screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { axe } from "jest-axe";
import { renderWithProviders } from "./helpers";

const submitReport = vi.fn(async () => ({ ok: true }));
vi.mock("@/app/report-actions", () => ({
  submitReport: (...args: unknown[]) => submitReport(...(args as [])),
}));

import { SafetyBanner } from "@/components/shared/SafetyBanner";

describe("SafetyBanner", () => {
  it("states the companionship-not-therapy framing on the page", async () => {
    const { container } = renderWithProviders(<SafetyBanner />);
    expect(
      screen.getByText(/companionship, not medical or mental-health care/i),
    ).toBeInTheDocument();
    expect(await axe(container)).toHaveNoViolations();
  });

  it("opens the crisis-support dialog from the inline link", async () => {
    const user = userEvent.setup();
    renderWithProviders(<SafetyBanner />);

    await user.click(
      screen.getByRole("button", { name: /if you're in crisis/i }),
    );

    expect(
      screen.getByRole("heading", { name: /finding support in a crisis/i }),
    ).toBeInTheDocument();
    expect(screen.getByText(/988 Suicide & Crisis Lifeline/i)).toBeInTheDocument();
  });

  it("hides the report hook when signed out, shows it when allowed", () => {
    const { rerender } = renderWithProviders(<SafetyBanner />);
    expect(
      screen.queryByRole("button", { name: /report a problem/i }),
    ).not.toBeInTheDocument();
    rerender(<SafetyBanner canReport />);
    expect(
      screen.getByRole("button", { name: /report a problem/i }),
    ).toBeInTheDocument();
  });

  it("sends a report with the reason", async () => {
    const user = userEvent.setup();
    renderWithProviders(<SafetyBanner canReport />);
    await user.click(screen.getByRole("button", { name: /report a problem/i }));
    await user.type(
      screen.getByLabelText(/what happened/i),
      "The call dropped twice.",
    );
    await user.click(screen.getByRole("button", { name: /send report/i }));
    expect(submitReport).toHaveBeenCalledWith({
      reason: "The call dropped twice.",
    });
  });
});

