import { test, expect } from "@playwright/test";
import { signIn, signOut } from "./utils";

/**
 * Happy path (b): a new listener signs up, completes onboarding, an admin
 * approves them, and they then appear in browse.
 * Requires a running local Supabase with the seed (`supabase db reset`).
 */
test("provider onboards, admin approves, and they appear in browse", async ({
  page,
}) => {
  const stamp = Date.now();
  const name = `E2E Listener ${stamp}`;
  const email = `e2e-provider-${stamp}@example.com`;

  // --- Sign up as a provider ---
  await page.goto("/signup");
  await page.getByLabel(/your name/i).fill(name);
  await page.getByLabel(/email address/i).fill(email);
  await page.getByLabel(/^password/i).fill("password123");
  await page.getByRole("radio", { name: /i want to be a listener/i }).click();
  await page.getByRole("button", { name: /create account/i }).click();
  await expect(page).toHaveURL(/\/provider\/dashboard/);

  // --- Onboarding ---
  await page.getByRole("link", { name: /finish setting up/i }).first().click();
  await expect(page).toHaveURL(/\/provider\/onboarding/);

  // Step 1: written intro.
  await page
    .getByLabel(/a short written intro/i)
    .fill("Hi, I'm an end-to-end listener who loves a calm chat.");
  await page.getByRole("button", { name: /^next$/i }).click();

  // Step 2: topics + languages.
  await page.getByRole("button", { name: "everyday chat" }).click();
  await page.getByRole("button", { name: "English" }).click();
  await page.getByRole("button", { name: /^next$/i }).click();

  // Step 3: prices.
  await page.getByLabel(/price for 15 minutes/i).fill("10");
  await page.getByLabel(/price for 30 minutes/i).fill("20");
  await page.getByLabel(/price for 45 minutes/i).fill("30");
  await page.getByLabel(/per-minute rate/i).fill("0.7");
  await page.getByRole("button", { name: /^next$/i }).click();

  // Step 4: submit.
  await page.getByRole("button", { name: /finish and submit/i }).click();
  await expect(page).toHaveURL(/\/provider\/dashboard/);

  await signOut(page);

  // --- Admin approves ---
  await signIn(page, "admin@heard.test", "password123");
  await page.goto("/admin/providers");
  const card = page.locator("li").filter({ hasText: name }).first();
  await expect(card).toBeVisible();
  await card.getByRole("button", { name: /approve/i }).click();

  await signOut(page);

  // --- They now appear in browse ---
  await signIn(page, "customer@heard.test", "password123");
  await page.goto("/browse");
  await expect(page.getByRole("heading", { name })).toBeVisible();
});

