"use client";

import * as React from "react";
import { Mic, MicOff, Captions, PhoneOff } from "lucide-react";
import { Avatar } from "@/components/ui/Avatar";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";

function fmt(totalSeconds: number): string {
  const m = Math.floor(totalSeconds / 60);
  const s = totalSeconds % 60;
  return `${m}:${String(s).padStart(2, "0")}`;
}

/** Animated speaking bars; static when muted and under reduced motion (CSS). */
function CallWaveform({ active }: { active: boolean }) {
  const bars = [14, 28, 20, 34, 16, 30, 24, 38, 18, 26];
  return (
    <span aria-hidden="true" className="flex h-10 items-center gap-1.5">
      {bars.map((h, i) => (
        <span
          key={i}
          className="w-1.5 rounded-full bg-accent"
          style={{
            height: active ? h : 6,
            animation: active
              ? "wf 0.9s var(--ease-warm) infinite alternate"
              : "none",
            animationDelay: `${i * 0.07}s`,
          }}
        />
      ))}
    </span>
  );
}

export interface CallStageProps {
  name: string;
  avatarColor: string;
  /** Called with the elapsed seconds (the timer is the source of truth). */
  onEnd: (elapsedSeconds: number) => Promise<void>;
  endLabel: string;
}

export function CallStage({ name, avatarColor, onEnd, endLabel }: CallStageProps) {
  const { announce } = useToast();
  const [elapsed, setElapsed] = React.useState(0);
  const [muted, setMuted] = React.useState(false);
  const [captionsOn, setCaptionsOn] = React.useState(false);
  const [ending, setEnding] = React.useState(false);
  const elapsedRef = React.useRef(0);

  React.useEffect(() => {
    announce(t("session.connectedAnnounce"), true);
    const id = window.setInterval(() => {
      elapsedRef.current += 1;
      setElapsed(elapsedRef.current);
    }, 1000);
    return () => window.clearInterval(id);
  }, [announce]);

  async function end() {
    setEnding(true);
    announce(t("session.endedAnnounce"), true);
    await onEnd(elapsedRef.current);
  }

  return (
    <div className="mx-auto flex w-full max-w-2xl flex-col items-center gap-7 rounded-lg border border-border bg-surface p-8 shadow-md max-md:p-6">
      <Avatar name={name} color={avatarColor} size={120} />

      <div className="flex flex-col items-center gap-2">
        <h1 className="text-h2">{name}</h1>
        <p className="flex items-center gap-2 text-base font-bold text-ink-soft">
          <CallWaveform active={!muted} />
          {muted ? t("session.muted") : t("session.speaking")}
        </p>
      </div>

      <p
        className="font-display text-display tabular-nums max-md:text-h1"
        role="timer"
        aria-label={t("session.timerLabel")}
      >
        {fmt(elapsed)}
      </p>

      {captionsOn ? (
        <p
          aria-live="polite"
          className="w-full rounded-card border border-border bg-bg p-4 text-base text-ink"
        >
          {t("session.captionsSample")}
        </p>
      ) : null}

      <div className="flex w-full flex-wrap items-center justify-center gap-3 border-t border-border pt-6">
        <button
          type="button"
          onClick={() => setMuted((m) => !m)}
          aria-pressed={muted}
          className="inline-flex min-h-12 items-center gap-2 rounded-btn border border-border-strong bg-surface px-5 text-base font-bold text-ink hover:bg-surface-sunk aria-pressed:bg-surface-sunk"
        >
          {muted ? (
            <MicOff size={20} strokeWidth={2} aria-hidden="true" />
          ) : (
            <Mic size={20} strokeWidth={2} aria-hidden="true" />
          )}
          {muted ? t("session.unmute") : t("session.mute")}
        </button>

        <button
          type="button"
          onClick={() => setCaptionsOn((c) => !c)}
          aria-pressed={captionsOn}
          className="inline-flex min-h-12 items-center gap-2 rounded-btn border border-border-strong bg-surface px-5 text-base font-bold text-ink hover:bg-surface-sunk aria-pressed:bg-primary-tint aria-pressed:text-primary-dark"
        >
          <Captions size={20} strokeWidth={2} aria-hidden="true" />
          {captionsOn ? t("session.captionsOn") : t("session.captionsOff")}
        </button>

        <button
          type="button"
          onClick={end}
          disabled={ending}
          className="inline-flex min-h-12 items-center gap-2 rounded-btn bg-alert px-6 text-base font-bold text-surface hover:brightness-95 disabled:opacity-60"
        >
          <PhoneOff size={20} strokeWidth={2} aria-hidden="true" />
          {ending ? t("session.ending") : endLabel}
        </button>
      </div>
    </div>
  );
}

