"use client";

import * as React from "react";
import { useRouter } from "next/navigation";
import { Phone, Mic } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Avatar } from "@/components/ui/Avatar";
import { CallStage } from "@/components/session/CallStage";
import { startSession, endSession } from "@/app/(customer)/session/actions";
import { t } from "@/lib/i18n";

export function SessionFlow({
  bookingId,
  name,
  avatarColor,
}: {
  bookingId: string;
  name: string;
  avatarColor: string;
}) {
  const router = useRouter();
  const [phase, setPhase] = React.useState<"precall" | "incall">("precall");
  const [joining, setJoining] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  async function join() {
    setJoining(true);
    setError(null);
    const res = await startSession(bookingId);
    if (res.error) {
      setError(res.error);
      setJoining(false);
      return;
    }
    setPhase("incall");
  }

  if (phase === "incall") {
    return (
      <CallStage
        name={name}
        avatarColor={avatarColor}
        endLabel={t("session.end")}
        onEnd={async (elapsed) => {
          await endSession(bookingId, elapsed);
          router.push(`/session/${bookingId}/summary`);
        }}
      />
    );
  }

  return (
    <Card className="mx-auto flex w-full max-w-xl flex-col items-center gap-6 p-8 text-center max-md:p-6">
      <Avatar name={name} color={avatarColor} size={96} />
      <span
        aria-hidden="true"
        className="flex items-center gap-2"
      >
        {[0, 1, 2].map((i) => (
          <span
            key={i}
            className="size-2.5 rounded-pill bg-primary"
            style={{
              animation: "wf 0.9s var(--ease-warm) infinite alternate",
              animationDelay: `${i * 0.15}s`,
            }}
          />
        ))}
      </span>
      <div className="flex flex-col gap-2">
        <h1 className="text-h2">{t("session.connectingTitle", { name })}</h1>
        <p className="text-lg text-ink-soft">{t("session.connectingHelp")}</p>
      </div>
      <p className="flex items-center gap-2 text-base font-bold text-success">
        <Mic size={18} strokeWidth={2} aria-hidden="true" />
        {t("session.micCheck")}
      </p>

      {error ? (
        <p role="alert" className="text-base font-semibold text-alert">
          {error}
        </p>
      ) : null}

      <div className="flex w-full flex-col gap-3">
        <Button full icon={Phone} onClick={join} disabled={joining}>
          {joining ? t("ui.loading") : t("session.join")}
        </Button>
        <Button full variant="ghost" onClick={() => router.push("/account")}>
          {t("session.cancel")}
        </Button>
      </div>
    </Card>
  );
}

