import "server-only";
import { createClient } from "@/lib/supabase/server";
import { PUBLIC_PROVIDER_COLUMNS } from "@/lib/supabase/types";
import {
  type AvailabilitySlotRow,
  type BookingRow,
  type PaymentRow,
  type PayoutRow,
  type ProviderRow,
  type PublicProvider,
  type ReviewRow,
  type SessionRow,
} from "@/lib/supabase/types";
import { type BrowseFilters } from "@/lib/validation/schemas";

/**
 * Central data-access layer (CLAUDE.md). All reads go through the RLS-enforced
 * server client, so each caller only sees rows they're entitled to. Public
 * provider reads select PUBLIC_PROVIDER_COLUMNS — never the server-only
 * bg_check_ref / payout_account_ref (no column-level RLS, so we scope here).
 */

/** Approved providers for discovery, with optional filters. */
export async function listApprovedProviders(
  filters: BrowseFilters = {},
): Promise<PublicProvider[]> {
  const supabase = await createClient();
  let query = supabase
    .from("providers")
    .select(PUBLIC_PROVIDER_COLUMNS)
    .eq("status", "approved");

  if (filters.topic) query = query.contains("topics", [filters.topic]);
  if (filters.language) query = query.contains("languages", [filters.language]);
  if (filters.availableNow) query = query.eq("is_available_now", true);
  if (typeof filters.maxPriceCents === "number") {
    query = query.lte("price_block_30_cents", filters.maxPriceCents);
  }

  const { data, error } = await query.order("rating_avg", { ascending: false });
  if (error) throw error;
  return (data ?? []) as unknown as PublicProvider[];
}

/** A single approved provider's public profile, or null. */
export async function getApprovedProvider(
  id: string,
): Promise<PublicProvider | null> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("providers")
    .select(PUBLIC_PROVIDER_COLUMNS)
    .eq("id", id)
    .eq("status", "approved")
    .maybeSingle();
  if (error) throw error;
  return (data as unknown as PublicProvider | null) ?? null;
}

/** Providers in a given status (admin only — RLS lets admins read all). */
export async function listProvidersByStatus(
  status: ProviderRow["status"],
): Promise<ProviderRow[]> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("providers")
    .select("*")
    .eq("status", status)
    .order("created_at", { ascending: true });
  if (error) throw error;
  return data ?? [];
}

/** All providers that aren't pending (admin only), newest first. */
export async function listDecidedProviders(): Promise<ProviderRow[]> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("providers")
    .select("*")
    .neq("status", "pending")
    .order("updated_at", { ascending: false });
  if (error) throw error;
  return data ?? [];
}

/** The signed-in provider's own full row (includes server-only fields). */
export async function getOwnProvider(): Promise<ProviderRow | null> {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return null;
  const { data, error } = await supabase
    .from("providers")
    .select("*")
    .eq("id", user.id)
    .maybeSingle();
  if (error) throw error;
  return data ?? null;
}

/** Public reviews for a provider, newest first. */
export async function listProviderReviews(
  providerId: string,
): Promise<ReviewRow[]> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("reviews")
    .select("*")
    .eq("provider_id", providerId)
    .order("created_at", { ascending: false });
  if (error) throw error;
  return data ?? [];
}

/** The review for a session, if one exists (one per session). */
export async function getReviewForSession(
  sessionId: string,
): Promise<ReviewRow | null> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("reviews")
    .select("*")
    .eq("session_id", sessionId)
    .maybeSingle();
  if (error) throw error;
  return data ?? null;
}

/** Future, unbooked availability slots for a provider. */
export async function listAvailabilitySlots(
  providerId: string,
): Promise<AvailabilitySlotRow[]> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("availability_slots")
    .select("*")
    .eq("provider_id", providerId)
    .eq("is_booked", false)
    .gt("start_at", new Date().toISOString())
    .order("start_at", { ascending: true });
  if (error) throw error;
  return data ?? [];
}

/** Bookings owned by the signed-in customer, newest first. */
export async function listCustomerBookings(
  customerId: string,
): Promise<BookingRow[]> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("bookings")
    .select("*")
    .eq("customer_id", customerId)
    .order("created_at", { ascending: false });
  if (error) throw error;
  return data ?? [];
}

/** Bookings made with the signed-in provider, newest first. */
export async function listProviderBookings(
  providerId: string,
): Promise<BookingRow[]> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("bookings")
    .select("*")
    .eq("provider_id", providerId)
    .order("created_at", { ascending: false });
  if (error) throw error;
  return data ?? [];
}

/** A single booking the caller is party to, or null. */
export async function getBooking(id: string): Promise<BookingRow | null> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("bookings")
    .select("*")
    .eq("id", id)
    .maybeSingle();
  if (error) throw error;
  return data ?? null;
}

/** The session for a booking the caller is party to, or null. */
export async function getSessionByBooking(
  bookingId: string,
): Promise<SessionRow | null> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("sessions")
    .select("*")
    .eq("booking_id", bookingId)
    .maybeSingle();
  if (error) throw error;
  return data ?? null;
}

/** A single session the caller is party to, or null. */
export async function getSession(id: string): Promise<SessionRow | null> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("sessions")
    .select("*")
    .eq("id", id)
    .maybeSingle();
  if (error) throw error;
  return data ?? null;
}

/** Payouts for the signed-in provider, newest period first. */
export async function listProviderPayouts(
  providerId: string,
): Promise<PayoutRow[]> {
