import { describe, it, expect } from "vitest";
import { render, screen, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { axe } from "jest-axe";
import { CircleCheck } from "lucide-react";
import { StatCard } from "@/components/ui/StatCard";
import { StatusBadge } from "@/components/ui/StatusBadge";
import { DataTable, type Column } from "@/components/ui/DataTable";

describe("StatCard", () => {
  it("shows a labeled number with no a11y violations", async () => {
    const { container } = render(
      <StatCard label="This week's earnings" value="$22.80" hint="2 sessions" />,
    );
    expect(screen.getByText("This week's earnings")).toBeInTheDocument();
    expect(screen.getByText("$22.80")).toBeInTheDocument();
    expect(await axe(container)).toHaveNoViolations();
  });
});

describe("StatusBadge", () => {
  it("carries text (and icon), not colour alone", async () => {
    const { container } = render(
      <StatusBadge tone="success" icon={CircleCheck}>
        Approved
      </StatusBadge>,
    );
    expect(screen.getByText("Approved")).toBeInTheDocument();
