import { useTransition } from "react";
import Link from "next/link";
import { Phone, X, Clock } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { StatusBadge } from "@/components/ui/StatusBadge";
import { declineBooking } from "@/app/(provider)/provider/actions";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";

export interface IncomingItem {
  id: string;
  blockMinutes: number;
  status: "confirmed" | "in_progress";
}

export function IncomingRequests({ items }: { items: IncomingItem[] }) {
  const [pending, startTransition] = useTransition();
  const { announce } = useToast();

  function decline(id: string) {
    startTransition(async () => {
      await declineBooking(id);
      announce(t("provider.decline"));
    });
  }

  if (items.length === 0) {
    return (
      <Card>
        <p className="text-base text-ink-soft">{t("provider.incomingNone")}</p>
      </Card>
    );
  }

  return (
    <ul className="flex flex-col gap-3">
      {items.map((item) => (
        <Card
          as="li"
          key={item.id}
          className="flex flex-wrap items-center justify-between gap-3"
        >
          <div className="flex items-center gap-3">
            <StatusBadge
              tone={item.status === "in_progress" ? "info" : "success"}
              icon={item.status === "in_progress" ? Clock : Phone}
            >
              {t("provider.guest")}
            </StatusBadge>
            <span className="text-base font-bold text-ink">
              {t("provider.minutesShort", { minutes: item.blockMinutes })}
            </span>
          </div>
          <div className="flex items-center gap-2">
            <Link href={`/provider/session/${item.id}`} className="rounded-btn">
              <Button icon={Phone}>{t("provider.accept")}</Button>
            </Link>
            <Button
              variant="ghost"
              icon={X}
              onClick={() => decline(item.id)}
              disabled={pending}
            >
              {t("provider.decline")}
            </Button>
          </div>
        </Card>
      ))}
    </ul>
  );
}

