"use client";

import * as React from "react";
import { DataTable, type Column } from "@/components/ui/DataTable";
import { formatCents } from "@/lib/format";
import { t } from "@/lib/i18n";

export interface SessionRowData {
  id: string;
  dateLabel: string;
  endedAtMs: number;
  durationLabel: string;
  blockMinutes: number;
  overageMinutes: number;
  earningsCents: number;
  rating: number | null;
}

export function SessionsTable({ rows }: { rows: SessionRowData[] }) {
  const columns: Column<SessionRowData>[] = [
    {
      key: "dateLabel",
      header: t("provider.colDate"),
      sortable: true,
      sortValue: (r) => r.endedAtMs,
    },
    { key: "durationLabel", header: t("provider.colDuration") },
    {
      key: "blockMinutes",
      header: t("provider.colBlock"),
      render: (r) => t("provider.minutesShort", { minutes: r.blockMinutes }),
    },
    {
      key: "overageMinutes",
      header: t("provider.colOverage"),
      render: (r) =>
        r.overageMinutes > 0
          ? t("provider.minutesShort", { minutes: r.overageMinutes })
          : t("provider.noRatingShort"),
    },
    {
      key: "earningsCents",
      header: t("provider.colEarnings"),
      align: "right",
      sortable: true,
      sortValue: (r) => r.earningsCents,
      render: (r) => formatCents(r.earningsCents),
    },
    {
      key: "rating",
      header: t("provider.colRating"),
      render: (r) => (r.rating ? `★ ${r.rating}` : t("provider.noRatingShort")),
    },
  ];

  return (
    <DataTable
      caption={t("provider.recentSessionsCaption")}
      columns={columns}
      rows={rows}
      getRowKey={(r) => r.id}
      emptyText={t("provider.recentSessionsNone")}
    />
  );
}

