import Link from "next/link";
import { ShieldCheck, ArrowRight } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { AvailabilityToggle } from "@/components/provider/AvailabilityToggle";
import { requireRole } from "@/lib/auth";
import {
  getOwnProvider,
  listProviderBookings,
  listProviderPayouts,
  getProviderEarningsSince,
  getProviderTipsSince,
} from "@/lib/db/queries";
import { formatCents, formatRating } from "@/lib/format";
import { isoDaysAgo } from "@/lib/time";
import { t, type MessageKey } from "@/lib/i18n";
import { type ProviderStatus } from "@/lib/supabase/types";

export const metadata = {
  title: `${t("provider.dashboardTitle")} · ${t("app.name")}`,
};

const STATUS_COPY: Record<
  ProviderStatus,
  { titleKey: MessageKey; bodyKey: MessageKey; tone: string }
> = {
  pending: {
    titleKey: "provider.statusPendingTitle",
    bodyKey: "provider.statusPendingBody",
    tone: "border-accent bg-accent-tint",
  },
  approved: {
    titleKey: "provider.statusApprovedTitle",
    bodyKey: "provider.statusApprovedBody",
    tone: "border-success bg-success-tint",
  },
  rejected: {
    titleKey: "provider.statusRejectedTitle",
    bodyKey: "provider.statusRejectedBody",
    tone: "border-alert bg-alert-tint",
  },
  suspended: {
    titleKey: "provider.statusSuspendedTitle",
    bodyKey: "provider.statusSuspendedBody",
    tone: "border-alert bg-alert-tint",
  },
};

export default async function ProviderDashboardPage() {
  const profile = await requireRole("provider");
  const provider = await getOwnProvider();

  const onboardingComplete =
    !!provider &&
    provider.bio.trim().length > 0 &&
    provider.topics.length > 0 &&
    provider.price_block_30_cents > 0;

  const weekAgo = isoDaysAgo(7);
  const [bookings, payouts, sessionEarnings, tips] = provider
    ? await Promise.all([
        listProviderBookings(provider.id),
        listProviderPayouts(provider.id),
        getProviderEarningsSince(provider.id, weekAgo),
        getProviderTipsSince(provider.id, weekAgo),
      ])
    : [[], [], 0, 0];
  const earnings = sessionEarnings + tips;

  const upcoming = bookings.filter(
    (b) => b.status === "confirmed" || b.status === "in_progress",
  );
  const status = provider?.status ?? "pending";
  const statusCopy = STATUS_COPY[status];

  return (
    <div className="flex flex-col gap-6">
      <h1 className="text-h1">
        {t("provider.welcomeBack", {
          name: provider?.display_name || profile.full_name,
        })}
      </h1>

      {!onboardingComplete ? (
        <Card className="flex flex-col gap-3 bg-primary-tint sm:flex-row sm:items-center sm:justify-between">
          <p className="text-lg font-bold text-ink">
            {t("provider.completeOnboarding")}
          </p>
          <Link href="/provider/onboarding" className="rounded-btn">
            <Button icon={ArrowRight}>{t("provider.completeOnboarding")}</Button>
          </Link>
        </Card>
      ) : null}

      <Card
        as="section"
        className={`flex items-start gap-3 border-l-4 ${statusCopy.tone}`}
      >
        <ShieldCheck size={22} aria-hidden="true" className="mt-0.5 text-ink" />
        <div>
          <h2 className="text-h3">{t(statusCopy.titleKey)}</h2>
          <p className="mt-1 text-base text-ink-soft">{t(statusCopy.bodyKey)}</p>
        </div>
      </Card>

      <Card as="section" className="flex flex-col gap-4">
        <h2 className="text-h3">{t("provider.availabilityHeading")}</h2>
        <AvailabilityToggle
          initial={provider?.is_available_now ?? false}
          disabled={status !== "approved"}
        />
      </Card>

      <div className="grid grid-cols-2 gap-4 max-md:grid-cols-1">
        <Card as="section" className="flex flex-col gap-1">
          <h2 className="text-h3">{t("provider.earningsHeading")}</h2>
          <p className="text-display max-md:text-h1">{formatCents(earnings)}</p>
          {earnings === 0 ? (
            <p className="text-base text-ink-soft">{t("provider.earningsNone")}</p>
          ) : null}
        </Card>
        <Card as="section" className="flex flex-col gap-1">
          <h2 className="text-h3">{t("provider.ratingHeading")}</h2>
          {provider && provider.rating_count > 0 ? (
            <p className="text-display max-md:text-h1">
              {t("provider.ratingValue", {
                avg: formatRating(provider.rating_avg),
                count: provider.rating_count,
              })}
            </p>
          ) : (
            <p className="text-base text-ink-soft">{t("provider.ratingNone")}</p>
          )}
        </Card>
      </div>

      <Card as="section" className="flex flex-col gap-3">
        <h2 className="text-h3">{t("provider.upcomingHeading")}</h2>
        {upcoming.length === 0 ? (
          <p className="text-base text-ink-soft">{t("provider.upcomingNone")}</p>
        ) : (
          <ul className="flex flex-col gap-2">
            {upcoming.map((b) => (
              <li
                key={b.id}
                className="flex items-center justify-between rounded-card border border-border px-4 py-3 text-base"
              >
                <span className="font-bold text-ink">{b.block_minutes} min</span>
                <span className="text-ink-soft">
                  {formatCents(b.price_block_cents)}
                </span>
              </li>
            ))}
          </ul>
        )}
      </Card>

      <Card as="section" className="flex flex-col gap-3">
        <h2 className="text-h3">{t("provider.payoutsHeading")}</h2>
        {payouts.length === 0 ? (
          <p className="text-base text-ink-soft">{t("provider.payoutsNone")}</p>
        ) : (
          <ul className="flex flex-col gap-2">
            {payouts.map((p) => (
              <li
                key={p.id}
                className="flex items-center justify-between rounded-card border border-border px-4 py-3 text-base"
              >
                <span className="text-ink-soft">
                  {new Date(p.period_end).toLocaleDateString("en-US")}
                </span>
                <span className="font-bold text-ink">
                  {formatCents(p.amount_cents)}
                </span>
              </li>
            ))}
          </ul>
        )}
      </Card>
    </div>
  );
}

