  const supabase = await createClient();
  const { data, error } = await supabase
    .from("providers")
    .select(PUBLIC_PROVIDER_COLUMNS)
    .in("id", ids)
    .eq("status", "approved");
  if (error) throw error;
  const rows = (data ?? []) as unknown as PublicProvider[];
  return new Map(rows.map((p) => [p.id, p]));
}

