import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Avatar } from "@/components/ui/Avatar";
import { Tag } from "@/components/ui/Tag";
import { Availability } from "@/components/ui/Availability";
import { VoicePlayer } from "@/components/ui/VoicePlayer";
import { FavoriteButton } from "@/components/customer/FavoriteButton";
import { formatBlockPrice } from "@/lib/format";
import { t } from "@/lib/i18n";
import { type PublicProvider } from "@/lib/supabase/types";

export function ListenerCard({
  provider,
  audioUrl,
  canFavorite = false,
  isFavorite = false,
}: {
  provider: PublicProvider;
  audioUrl: string | null;
  canFavorite?: boolean;
  isFavorite?: boolean;
}) {
  return (
    <Card as="li" className="flex flex-col gap-4">
      <div className="flex items-start gap-3">
        <Avatar name={provider.display_name} color={provider.avatar_color} />
        <div className="min-w-0 flex-1">
          <h2 className="text-h3">{provider.display_name}</h2>
          <p className="text-base font-bold text-ink-soft">
            {provider.rating_count > 0
              ? `${provider.rating_avg.toFixed(1)} (${provider.rating_count})`
              : ""}
          </p>
        </div>
        <div className="flex flex-col items-end gap-2">
          <Availability
            status={provider.is_available_now ? "available" : "scheduled"}
          />
          {canFavorite ? (
            <FavoriteButton
              providerId={provider.id}
              providerName={provider.display_name}
              initialFavorite={isFavorite}
            />
          ) : null}
        </div>
      </div>

      <VoicePlayer
        name={provider.display_name}
        intro={provider.bio}
        audioUrl={audioUrl}
      />

      <ul className="flex flex-wrap gap-2">
        {provider.topics.slice(0, 3).map((topic) => (
          <li key={topic}>
            <Tag>{topic}</Tag>
          </li>
        ))}
      </ul>

      <div className="mt-auto flex items-center justify-between gap-3 border-t border-border pt-4">
        <span className="text-base font-bold text-ink">
          {formatBlockPrice(provider.price_block_30_cents, 30)}
        </span>
        <Link
          href={`/listeners/${provider.id}`}
          className="inline-flex min-h-12 items-center gap-2 rounded-btn bg-primary px-5 text-base font-bold text-surface hover:bg-primary-dark"
        >
          {t("browse.viewProfile", { name: provider.display_name })}
          <ArrowRight size={18} strokeWidth={2} aria-hidden="true" />
        </Link>
      </div>
    </Card>
  );
}

