import Link from "next/link";
import { notFound } from "next/navigation";
import { ChevronLeft, Phone, CalendarDays } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Tag } from "@/components/ui/Tag";
import { Avatar } from "@/components/ui/Avatar";
import { Availability } from "@/components/ui/Availability";
import { VoicePlayer } from "@/components/ui/VoicePlayer";
import { getApprovedProvider, listProviderReviews } from "@/lib/db/queries";
import { getVoiceIntroSignedUrl } from "@/lib/storage";
import { formatBlockPrice } from "@/lib/format";
import { t } from "@/lib/i18n";

export default async function ListenerProfilePage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;
  const provider = await getApprovedProvider(id);
  if (!provider) notFound();

  const [reviews, audioUrl] = await Promise.all([
    listProviderReviews(id),
    getVoiceIntroSignedUrl(provider.voice_intro_path),
  ]);

  return (
    <div className="flex flex-col gap-6">
      <Link
        href="/browse"
        className="inline-flex items-center gap-1.5 self-start rounded-sm text-base font-bold text-primary"
      >
        <ChevronLeft size={20} strokeWidth={2} aria-hidden="true" />
        {t("listener.backToBrowse")}
      </Link>

      <div className="flex items-start gap-4">
        <Avatar name={provider.display_name} color={provider.avatar_color} size={72} />
        <div className="flex-1">
          <h1 className="text-h1">{provider.display_name}</h1>
          <div className="mt-2 flex flex-wrap items-center gap-3">
            <Availability
              status={provider.is_available_now ? "available" : "scheduled"}
            />
            {provider.rating_count > 0 ? (
              <span className="text-base font-bold text-ink-soft">
                {provider.rating_avg.toFixed(1)} ({provider.rating_count})
              </span>
            ) : null}
          </div>
        </div>
      </div>

      <VoicePlayer
        name={provider.display_name}
        intro={provider.bio}
        big
        audioUrl={audioUrl}
      />

      <div className="flex flex-wrap gap-3">
        {provider.is_available_now ? (
          <Link href={`/book/${provider.id}?mode=now`} className="rounded-btn">
            <Button icon={Phone}>{t("listener.talkNow")}</Button>
          </Link>
        ) : null}
        <Link href={`/book/${provider.id}?mode=scheduled`} className="rounded-btn">
          <Button variant={provider.is_available_now ? "ghost" : "primary"} icon={CalendarDays}>
            {t("listener.schedule")}
          </Button>
        </Link>
      </div>

      <Card as="section" className="flex flex-col gap-3">
        <h2 className="text-h3">{t("listener.topicsHeading")}</h2>
        <ul className="flex flex-wrap gap-2">
          {provider.topics.map((topic) => (
            <li key={topic}>
              <Tag>{topic}</Tag>
            </li>
          ))}
        </ul>
        <h2 className="mt-2 text-h3">{t("listener.languagesHeading")}</h2>
        <p className="text-base text-ink">{provider.languages.join(", ")}</p>
      </Card>

      <Card as="section" className="flex flex-col gap-3">
        <h2 className="text-h3">{t("listener.pricingHeading")}</h2>
        <p className="text-base text-ink">
          {formatBlockPrice(provider.price_block_15_cents, 15)} ·{" "}
          {formatBlockPrice(provider.price_block_30_cents, 30)} ·{" "}
          {formatBlockPrice(provider.price_block_45_cents, 45)}
        </p>
      </Card>

      <section className="flex flex-col gap-3">
        <h2 className="text-h2">{t("listener.reviewsHeading")}</h2>
        {reviews.length === 0 ? (
          <Card>
            <p className="text-base text-ink-soft">{t("listener.noReviews")}</p>
          </Card>
        ) : (
          <ul className="flex flex-col gap-3">
            {reviews.map((review) => (
              <Card as="li" key={review.id} className="flex flex-col gap-1.5">
                <p className="text-base text-ink">{review.comment}</p>
                <p className="text-sm font-bold text-ink-soft">
                  ★ {review.rating}
                </p>
              </Card>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { ChevronLeft, Phone, CalendarDays } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Tag } from "@/components/ui/Tag";
import { Avatar } from "@/components/ui/Avatar";
import { Availability } from "@/components/ui/Availability";
import { VoicePlayer } from "@/components/ui/VoicePlayer";
import { FavoriteButton } from "@/components/customer/FavoriteButton";
import {
  getApprovedProvider,
  listProviderReviews,
  listFavoriteIds,
} from "@/lib/db/queries";
import { getVoiceIntroSignedUrl } from "@/lib/storage";
import { getProfile } from "@/lib/auth";
import { formatBlockPrice } from "@/lib/format";
import { t } from "@/lib/i18n";

export default async function ListenerProfilePage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;
  const provider = await getApprovedProvider(id);
  if (!provider) notFound();

  const profile = await getProfile();
  const isCustomer = profile?.role === "customer";
  const [reviews, audioUrl, favoriteIds] = await Promise.all([
    listProviderReviews(id),
    getVoiceIntroSignedUrl(provider.voice_intro_path),
    isCustomer ? listFavoriteIds(profile.id) : Promise.resolve([]),
  ]);
  const isFavorite = favoriteIds.includes(id);

  return (
    <div className="flex flex-col gap-6">
      <Link
        href="/browse"
        className="inline-flex items-center gap-1.5 self-start rounded-sm text-base font-bold text-primary"
      >
        <ChevronLeft size={20} strokeWidth={2} aria-hidden="true" />
        {t("listener.backToBrowse")}
      </Link>

      <div className="flex items-start gap-4">
        <Avatar name={provider.display_name} color={provider.avatar_color} size={72} />
        <div className="flex-1">
          <h1 className="text-h1">{provider.display_name}</h1>
          <div className="mt-2 flex flex-wrap items-center gap-3">
            <Availability
              status={provider.is_available_now ? "available" : "scheduled"}
            />
            {provider.rating_count > 0 ? (
              <span className="text-base font-bold text-ink-soft">
                {provider.rating_avg.toFixed(1)} ({provider.rating_count})
              </span>
            ) : null}
          </div>
