import { describe, it, expect, vi } from "vitest";
import { screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { axe } from "jest-axe";
import { renderWithProviders } from "./helpers";

const addFavorite = vi.fn(async () => ({ ok: true }));
const removeFavorite = vi.fn(async () => ({ ok: true }));
const cancelBooking = vi.fn(async () => ({ ok: true, released: true }));
const rescheduleBooking = vi.fn(async () => ({ ok: true }));
vi.mock("@/app/(customer)/account/actions", () => ({
  addFavorite: (...a: unknown[]) => addFavorite(...(a as [])),
  removeFavorite: (...a: unknown[]) => removeFavorite(...(a as [])),
  cancelBooking: (...a: unknown[]) => cancelBooking(...(a as [])),
  rescheduleBooking: (...a: unknown[]) => rescheduleBooking(...(a as [])),
}));

import { FavoriteButton } from "@/components/customer/FavoriteButton";
import { UpcomingBookings } from "@/components/customer/UpcomingBookings";
import { PastSessionsTable } from "@/components/customer/PastSessionsTable";

describe("FavoriteButton", () => {
  it("exposes pressed state and toggles, no a11y violations", async () => {
    const user = userEvent.setup();
    const { container } = renderWithProviders(
      <FavoriteButton providerId="p1" providerName="Maya" initialFavorite={false} />,
    );
    const btn = screen.getByRole("button", { name: /save maya to favorites/i });
    expect(btn).toHaveAttribute("aria-pressed", "false");
    expect(await axe(container)).toHaveNoViolations();
    await user.click(btn);
    expect(addFavorite).toHaveBeenCalledWith("p1");
    expect(
      screen.getByRole("button", { name: /remove maya from favorites/i }),
    ).toHaveAttribute("aria-pressed", "true");
  });
});

describe("UpcomingBookings", () => {
