import * as React from "react";
import { type LucideIcon } from "lucide-react";

export type StatusTone = "neutral" | "success" | "warning" | "alert" | "info";

const TONES: Record<StatusTone, string> = {
  neutral: "bg-surface-sunk text-ink-soft",
  success: "bg-success-tint text-success",
  warning: "bg-accent-tint text-accent-dark",
  alert: "bg-alert-tint text-alert",
  info: "bg-primary-tint text-primary-dark",
};

/**
 * Generic status pill. Meaning is carried by the icon + text label together —
 * never by colour alone (the tone is reinforcement, not the signal).
 */
export function StatusBadge({
  tone = "neutral",
  icon: Icon,
  children,
}: {
  tone?: StatusTone;
  icon?: LucideIcon;
  children: React.ReactNode;
}) {
  return (
    <span
      className={[
        "inline-flex items-center gap-1.5 whitespace-nowrap rounded-pill px-2.5 py-1 text-sm font-bold",
        TONES[tone],
      ].join(" ")}
    >
      {Icon ? <Icon size={15} strokeWidth={2.25} aria-hidden="true" /> : null}
      {children}
    </span>
  );
}

