import Link from "next/link";
import { Phone } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Avatar } from "@/components/ui/Avatar";
import { Availability } from "@/components/ui/Availability";
import { VoicePlayer } from "@/components/ui/VoicePlayer";
import { FavoriteButton } from "@/components/customer/FavoriteButton";
import { t } from "@/lib/i18n";
import { type PublicProvider } from "@/lib/supabase/types";

export function FavoriteListeners({
  items,
}: {
  items: { provider: PublicProvider; audioUrl: string | null }[];
}) {
  if (items.length === 0) {
    return (
      <Card>
        <p className="text-base text-ink-soft">{t("account.favoritesNone")}</p>
      </Card>
    );
  }

  return (
    <ul className="grid grid-cols-2 gap-5 max-md:grid-cols-1">
      {items.map(({ provider, audioUrl }) => (
        <Card as="li" key={provider.id} className="flex flex-col gap-4">
          <div className="flex items-start gap-3">
            <Avatar name={provider.display_name} color={provider.avatar_color} />
            <div className="min-w-0 flex-1">
              <h3 className="text-h3">{provider.display_name}</h3>
              <Availability
                status={provider.is_available_now ? "available" : "scheduled"}
              />
            </div>
            <FavoriteButton
              providerId={provider.id}
              providerName={provider.display_name}
              initialFavorite
            />
          </div>
          <VoicePlayer
            name={provider.display_name}
            intro={provider.bio}
            audioUrl={audioUrl}
          />
          <Link
            href={`/book/${provider.id}${provider.is_available_now ? "?mode=now" : ""}`}
            className="rounded-btn"
          >
            <Button full icon={Phone}>
              {t("account.rebook")}
            </Button>
          </Link>
        </Card>
      ))}
    </ul>
  );
}

