import { test, expect } from "@playwright/test";
import { signIn } from "./utils";

/**
 * Dashboard happy paths (M14). Each exercises one of the three dashboards
 * end-to-end against the seeded Casey↔Maya history.
 * Requires a running local Supabase with the seed (`supabase db reset`).
 */

// (a) A listener views their earnings & payouts.
test("provider sees real earnings and payout history", async ({ page }) => {
  await signIn(page, "maya@heard.test", "password123");
  await page.goto("/provider/dashboard");

  // At-a-glance + earnings cards reflect the seeded sessions (+ tip).
  await expect(
    page.getByRole("heading", { name: /this week/i }).first(),
  ).toBeVisible();
  // Lifetime = 3 sessions (6080¢) + a 500¢ tip = $65.80 — proves the cents math.
  await expect(page.getByText("$65.80").first()).toBeVisible();

  // Payout history table shows the paid + scheduled payouts.
  await expect(
    page.getByRole("heading", { name: /payout history/i }),
  ).toBeVisible();
  const payouts = page.getByRole("table", { name: /payout history/i });
  await expect(payouts.getByText("$22.80")).toBeVisible();
  await expect(payouts.getByText("$43.00")).toBeVisible();
});

// (b) A customer rebooks from their favorite listeners.
test("customer rebooks a favorite listener", async ({ page }) => {
  await signIn(page, "customer@heard.test", "password123");
  await page.goto("/account");

  // Favorites section is seeded with Maya and Walter.
  await expect(
    page.getByRole("heading", { name: /favorite listeners/i }),
  ).toBeVisible();
  const mayaCard = page
    .getByRole("listitem")
    .filter({ hasText: "Maya" })
    .first();
  await expect(mayaCard).toBeVisible();

  // Rebook → lands on the booking screen for that listener.
  await mayaCard.getByRole("link", { name: /rebook/i }).click();
  await expect(page).toHaveURL(/\/book\//);
  await expect(
    page.getByRole("button", { name: /confirm & connect/i }),
  ).toBeVisible();
});

// (c) An admin actions a safety report.
test("admin marks a report reviewed", async ({ page }) => {
  await signIn(page, "admin@heard.test", "password123");
  await page.goto("/admin/reports");

  // The seeded report (Walter about Casey) starts Open.
  const card = page
    .getByRole("listitem")
    .filter({ hasText: /walter/i })
    .first();
  await expect(card).toBeVisible();
  await expect(card.getByText("Open", { exact: true })).toBeVisible();

  // Mark it reviewed; the status flips and the action is removed.
  await card.getByRole("button", { name: /mark reviewed/i }).click();
  await expect(card.getByText("Reviewed", { exact: true })).toBeVisible();
  await expect(
    card.getByRole("button", { name: /mark reviewed/i }),
  ).toHaveCount(0);
});

