import Link from "next/link";
import { CircleCheck, Phone, Settings, Download } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { StatusBadge } from "@/components/ui/StatusBadge";
import { DashboardHeader } from "@/components/dashboard/DashboardHeader";
import { FavoriteListeners } from "@/components/customer/FavoriteListeners";
import { UpcomingBookings } from "@/components/customer/UpcomingBookings";
import { PastSessionsTable } from "@/components/customer/PastSessionsTable";
import { requireRole } from "@/lib/auth";
import {
  listCustomerBookings,
  listCustomerCompletedSessions,
  listCustomerPayments,
  listCustomerReviews,
  listFavoriteProviders,
  getApprovedProvidersByIds,
} from "@/lib/db/queries";
import { getVoiceIntroSignedUrl } from "@/lib/storage";
import { formatCents } from "@/lib/format";
import { shortDate, durationLabel } from "@/lib/time";
import { t } from "@/lib/i18n";

export const metadata = { title: `${t("account.title")} · ${t("app.name")}` };

export default async function AccountPage({
  searchParams,
}: {
  searchParams: Promise<{ booked?: string }>;
}) {
  const profile = await requireRole("customer");
  const { booked } = await searchParams;

  const [bookings, sessions, payments, reviews, favorites] = await Promise.all([
    listCustomerBookings(profile.id),
    listCustomerCompletedSessions(profile.id),
    listCustomerPayments(profile.id),
    listCustomerReviews(profile.id),
    listFavoriteProviders(profile.id),
  ]);

  // Resolve listener names for bookings + sessions.
  const providerIds = Array.from(
    new Set([
      ...bookings.map((b) => b.provider_id),
      ...sessions.map((s) => s.provider_id),
    ]),
  );
  const providersById = await getApprovedProvidersByIds(providerIds);
  const nameFor = (id: string) => providersById.get(id)?.display_name ?? "—";

  const favoritesWithAudio = await Promise.all(
    favorites.map(async (provider) => ({
      provider,
      audioUrl: await getVoiceIntroSignedUrl(provider.voice_intro_path),
    })),
  );

  // Sort by actual chronology: in-progress first, then "now" bookings, then
  // scheduled by their time — so "Next session" is the soonest, not the latest
  // created.
  const sortKey = (b: (typeof bookings)[number]) =>
    b.status === "in_progress"
      ? 0
      : b.scheduled_at
        ? new Date(b.scheduled_at).getTime()
        : 1; // a "now" booking is imminent
  const upcoming = bookings
    .filter((b) => b.status === "confirmed" || b.status === "in_progress")
    .sort((a, b) => sortKey(a) - sortKey(b))
    .map((b) => ({
      id: b.id,
      providerName: nameFor(b.provider_id),
      blockMinutes: b.block_minutes,
      status: b.status as "confirmed" | "in_progress",
      whenLabel: b.scheduled_at
        ? shortDate(b.scheduled_at)
        : t("account.talkNow"),
    }));

  const next = upcoming[0];

  const reviewedSessionIds = new Set(
    reviews.map((r) => r.session_id).filter(Boolean),
  );
  // Receipts only make sense for completed sessions; an authorized hold on an
  // upcoming booking has no receipt yet.
  const completedBookingIds = new Set(sessions.map((s) => s.booking_id));
  const PAY_STATUS: Record<
    string,
    { labelKey: "account.payAuthorized" | "account.payCaptured" | "account.payRefunded" | "account.payFailed"; tone: "success" | "neutral" | "alert" }
  > = {
    authorized: { labelKey: "account.payAuthorized", tone: "neutral" },
    captured: { labelKey: "account.payCaptured", tone: "success" },
    refunded: { labelKey: "account.payRefunded", tone: "neutral" },
    failed: { labelKey: "account.payFailed", tone: "alert" },
  };
  const receipts = payments
    .filter((p) => completedBookingIds.has(p.booking_id))
    .map((p) => {
      const booking = bookings.find((b) => b.id === p.booking_id);
      const name = booking ? nameFor(booking.provider_id) : "—";
      return {
        id: p.id,
        bookingId: p.booking_id,
        amountCents: p.amount_cents,
        status: p.status,
        dateLabel: shortDate(p.created_at),
        listenerName: name,
      };
    });
  const pastRows = sessions.map((s) => ({
    id: s.id,
    bookingId: s.booking_id,
    dateLabel: shortDate(s.ended_at),
    endedAtMs: s.ended_at ? new Date(s.ended_at).getTime() : 0,
    listenerName: nameFor(s.provider_id),
    durationLabel: durationLabel(s.elapsed_seconds),
    amountCents: s.total_price_cents,
    hasReview: reviewedSessionIds.has(s.id),
  }));

  return (
    <div className="flex flex-col gap-8">
      <DashboardHeader
        title={t("account.title")}
        description={t("account.subtitle")}
        action={
          <Link href="/account/settings" className="rounded-btn">
            <Button variant="ghost" icon={Settings}>
              {t("account.settingsLink")}
            </Button>
          </Link>
        }
      />

      {booked ? (
        <Card
          role="status"
          className="flex items-center gap-3 border-l-4 border-success bg-success-tint"
        >
          <CircleCheck size={22} aria-hidden="true" className="text-success" />
          <p className="text-base font-bold text-ink">
            {t("account.bookedConfirmed")}
          </p>
        </Card>
      ) : null}

      {/* Resume / quick start */}
      <Card
        as="section"
        className="flex flex-col gap-4 bg-primary-tint sm:flex-row sm:items-center sm:justify-between"
      >
        <div className="flex flex-col gap-1">
          <h2 className="text-h3">{t("account.resumeHeading")}</h2>
          <p className="text-base text-ink-soft">
            {next
              ? `${t("account.nextSession")}: ${next.providerName} · ${next.whenLabel}`
              : t("account.nextSessionNone")}
          </p>
        </div>
        <div className="flex flex-wrap gap-3">
          {next ? (
            <Link href={`/session/${next.id}`} className="rounded-btn">
              <Button variant="ghost">{t("account.join")}</Button>
            </Link>
          ) : null}
          <Link href="/browse?available=1" className="rounded-btn">
            <Button icon={Phone}>{t("account.talkNow")}</Button>
          </Link>
        </div>
      </Card>

      {/* Favorites */}
      <section className="flex flex-col gap-4">
        <h2 className="text-h2">{t("account.favoritesHeading")}</h2>
        <FavoriteListeners items={favoritesWithAudio} />
      </section>

      {/* Upcoming bookings */}
      <section className="flex flex-col gap-4">
        <h2 className="text-h2">{t("account.upcomingHeading")}</h2>
        <UpcomingBookings items={upcoming} />
      </section>

      {/* Past sessions */}
      <section className="flex flex-col gap-4">
        <h2 className="text-h2">{t("account.pastHeading")}</h2>
        <PastSessionsTable rows={pastRows} />
      </section>

      {/* Receipts */}
      <section className="flex flex-col gap-4">
        <h2 className="text-h2">{t("account.receiptsHeading")}</h2>
        {receipts.length === 0 ? (
          <Card>
            <p className="text-base text-ink-soft">{t("account.receiptsNone")}</p>
          </Card>
        ) : (
          <ul className="flex flex-col gap-3">
            {receipts.map((r) => {
              const pay = PAY_STATUS[r.status] ?? {
                labelKey: "account.payAuthorized" as const,
                tone: "neutral" as const,
              };
              return (
                <Card
                  as="li"
                  key={r.id}
                  className="flex flex-wrap items-center justify-between gap-3"
                >
                  <div className="flex items-center gap-3">
                    <span className="text-base font-bold text-ink">
                      {formatCents(r.amountCents)}
                    </span>
                    <StatusBadge tone={pay.tone}>{t(pay.labelKey)}</StatusBadge>
                    <span className="text-sm text-ink-soft">
                      {r.listenerName} · {r.dateLabel}
                    </span>
                  </div>
                  <a
                    href={`/account/receipt/${r.bookingId}`}
                    aria-label={t("account.downloadFor", {
                      name: r.listenerName,
                      date: r.dateLabel,
                    })}
                    className="inline-flex items-center gap-1.5 text-base font-bold text-primary underline underline-offset-[3px]"
                  >
                    <Download size={16} strokeWidth={2} aria-hidden="true" />
                    {t("account.download")}
                  </a>
                </Card>
              );
            })}
          </ul>
        )}
      </section>
    </div>
  );
}

