import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Availability } from "@/components/ui/Availability";
import { requireRole } from "@/lib/auth";
import { listProviderBookings } from "@/lib/db/queries";
import { t } from "@/lib/i18n";

export const metadata = {
  title: `${t("provider.sessionsTitle")} · ${t("app.name")}`,
};

export default async function ProviderSessionsPage() {
  const profile = await requireRole("provider");
  const bookings = await listProviderBookings(profile.id);
  const active = bookings.filter(
    (b) => b.status === "confirmed" || b.status === "in_progress",
  );

  return (
    <div className="flex flex-col gap-6">
      <div className="flex flex-col gap-1.5">
        <h1 className="text-h1">{t("provider.sessionsTitle")}</h1>
        <p className="text-lg text-ink-soft">{t("provider.sessionsSubtitle")}</p>
      </div>

      {active.length === 0 ? (
        <Card>
          <p className="text-base text-ink-soft">{t("provider.sessionsNone")}</p>
        </Card>
      ) : (
        <ul className="flex flex-col gap-3">
          {active.map((b) => (
            <Card
              as="li"
              key={b.id}
              className="flex flex-wrap items-center justify-between gap-3"
            >
              <div className="flex items-center gap-3">
                <Availability
                  status={b.status === "in_progress" ? "busy" : "available"}
                />
                <span className="text-base font-bold text-ink">
                  {t("provider.sessionReqLabel", { minutes: b.block_minutes })}
                </span>
              </div>
              <Link href={`/provider/session/${b.id}`} className="rounded-btn">
                <Button icon={ArrowRight}>{t("provider.openSession")}</Button>
              </Link>
            </Card>
          ))}
        </ul>
      )}
    </div>
  );
}

