import { Card } from "@/components/ui/Card";
import { ProviderApprovalCard } from "@/components/admin/ProviderApprovalCard";
import { PayoutRunner } from "@/components/admin/PayoutRunner";
import { requireRole } from "@/lib/auth";
import { listProvidersByStatus, listDecidedProviders } from "@/lib/db/queries";
import { getVoiceIntroSignedUrl } from "@/lib/storage";
import { t } from "@/lib/i18n";
import { type ProviderRow } from "@/lib/supabase/types";

export const metadata = { title: `${t("admin.title")} · ${t("app.name")}` };

async function withAudio(providers: ProviderRow[]) {
  return Promise.all(
    providers.map(async (provider) => ({
      provider,
      audioUrl: await getVoiceIntroSignedUrl(provider.voice_intro_path),
    })),
  );
}

export default async function AdminProvidersPage() {
  await requireRole("admin");
  const [pending, decided] = await Promise.all([
    listProvidersByStatus("pending"),
    listDecidedProviders(),
  ]);
  const [pendingWithAudio, decidedWithAudio] = await Promise.all([
    withAudio(pending),
    withAudio(decided),
  ]);

  return (
    <div className="flex flex-col gap-8">
      <div className="flex flex-col gap-1.5">
        <h1 className="text-h1">{t("admin.title")}</h1>
        <p className="text-lg text-ink-soft">{t("admin.subtitle")}</p>
      </div>

      <PayoutRunner />

      <section className="flex flex-col gap-4">
        <h2 className="text-h2">{t("admin.pendingHeading")}</h2>
        {pendingWithAudio.length === 0 ? (
          <Card>
            <p className="text-base text-ink-soft">{t("admin.pendingNone")}</p>
          </Card>
        ) : (
          <ul className="flex flex-col gap-4">
            {pendingWithAudio.map(({ provider, audioUrl }) => (
              <ProviderApprovalCard
                key={provider.id}
                provider={provider}
                audioUrl={audioUrl}
              />
            ))}
          </ul>
        )}
      </section>

      <section className="flex flex-col gap-4">
        <h2 className="text-h2">{t("admin.otherHeading")}</h2>
        {decidedWithAudio.length === 0 ? (
          <Card>
            <p className="text-base text-ink-soft">{t("admin.otherNone")}</p>
          </Card>
        ) : (
          <ul className="flex flex-col gap-4">
            {decidedWithAudio.map(({ provider, audioUrl }) => (
              <ProviderApprovalCard
                key={provider.id}
                provider={provider}
                audioUrl={audioUrl}
              />
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

import Link from "next/link";
import { ChevronLeft, CreditCard, Bell, Globe, Mail } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { StatusBadge } from "@/components/ui/StatusBadge";
import { DashboardHeader } from "@/components/dashboard/DashboardHeader";
import { NameSettingForm } from "@/components/customer/NameSettingForm";
import { requireRole } from "@/lib/auth";
import { t } from "@/lib/i18n";

export const metadata = {
  title: `${t("account.settingsTitle")} · ${t("app.name")}`,
};

export default async function SettingsPage() {
  const profile = await requireRole("customer");

  return (
    <div className="flex flex-col gap-6">
      <Link
        href="/account"
        className="inline-flex items-center gap-1.5 self-start rounded-sm text-base font-bold text-primary"
      >
        <ChevronLeft size={20} strokeWidth={2} aria-hidden="true" />
        {t("account.back")}
      </Link>

      <DashboardHeader
        title={t("account.settingsTitle")}
        description={t("account.settingsSubtitle")}
      />

      <Card as="section" className="flex flex-col gap-3">
        <h2 className="text-h3">{t("account.yourNameLabel")}</h2>
        <NameSettingForm initialName={profile.full_name} />
      </Card>

      <Card as="section">
        <dl className="flex flex-col gap-4">
          <div className="flex items-center justify-between gap-3">
            <dt className="flex items-center gap-2 text-base font-bold text-ink">
              <Mail size={18} strokeWidth={2} aria-hidden="true" className="text-ink-soft" />
              {t("account.emailLabel")}
            </dt>
            <dd className="text-base text-ink-soft">{profile.email}</dd>
          </div>
          <div className="flex items-center justify-between gap-3 border-t border-border pt-4">
            <dt className="flex items-center gap-2 text-base font-bold text-ink">
              <CreditCard size={18} strokeWidth={2} aria-hidden="true" className="text-ink-soft" />
              {t("account.paymentMethodLabel")}
            </dt>
            <dd className="text-base text-ink-soft">
              {t("account.paymentMethodValue")}
            </dd>
          </div>
          <div className="flex items-center justify-between gap-3 border-t border-border pt-4">
            <dt className="flex items-center gap-2 text-base font-bold text-ink">
              <Bell size={18} strokeWidth={2} aria-hidden="true" className="text-ink-soft" />
              {t("account.notificationsLabel")}
            </dt>
            <dd>
              <StatusBadge tone="success">{t("account.notificationsOn")}</StatusBadge>
            </dd>
          </div>
          <div className="flex items-center justify-between gap-3 border-t border-border pt-4">
            <dt className="flex items-center gap-2 text-base font-bold text-ink">
              <Globe size={18} strokeWidth={2} aria-hidden="true" className="text-ink-soft" />
              {t("account.languageLabel")}
            </dt>
            <dd className="text-base text-ink-soft">{t("account.languageValue")}</dd>
          </div>
        </dl>
      </Card>

      <p className="text-sm text-ink-soft">{t("account.settingsMockNote")}</p>
    </div>
  );
}

