describe("StatCard", () => {
  it("shows a labeled number with no a11y violations", async () => {
    const { container } = render(
      <StatCard label="This week's earnings" value="$22.80" hint="2 sessions" />,
    );
    expect(screen.getByText("This week's earnings")).toBeInTheDocument();
