    expect(await axe(container)).toHaveNoViolations();
  });
});

describe("StatusBadge", () => {
  it("carries text (and icon), not colour alone", async () => {
    const { container } = render(
      <StatusBadge tone="success" icon={CircleCheck}>
        Approved
      </StatusBadge>,
    );
    expect(screen.getByText("Approved")).toBeInTheDocument();
    expect(await axe(container)).toHaveNoViolations();
  });
});

interface Row {
  id: string;
  name: string;
  amount: number;
}
const ROWS: Row[] = [
  { id: "a", name: "Theo", amount: 2100 },
  { id: "b", name: "Maya", amount: 2400 },
  { id: "c", name: "Omar", amount: 1200 },
];
const COLUMNS: Column<Row>[] = [
  { key: "name", header: "Listener", sortable: true },
  {
    key: "amount",
    header: "Amount",
    align: "right",
    sortable: true,
    render: (r) => `$${(r.amount / 100).toFixed(2)}`,
    sortValue: (r) => r.amount,
  },
];

describe("DataTable", () => {
  it("renders a semantic table with caption and column headers", async () => {
    const { container } = render(
      <DataTable
        caption="Recent payouts"
        columns={COLUMNS}
        rows={ROWS}
        getRowKey={(r) => r.id}
      />,
    );
    expect(screen.getByRole("table", { name: "Recent payouts" })).toBeInTheDocument();
    const headers = screen.getAllByRole("columnheader");
    expect(headers).toHaveLength(2);
    expect(headers[0]).toHaveAttribute("scope", "col");
    expect(await axe(container)).toHaveNoViolations();
  });

  it("sorts on a header click and reflects aria-sort + announces it", async () => {
    const user = userEvent.setup();
    render(
      <DataTable
        caption="Recent payouts"
        columns={COLUMNS}
        rows={ROWS}
        getRowKey={(r) => r.id}
      />,
    );

    // Sort by Amount ascending.
    await user.click(screen.getByRole("button", { name: /amount/i }));
    const amountHeader = screen
      .getAllByRole("columnheader")
      .find((h) => within(h).queryByRole("button", { name: /amount/i }))!;
    expect(amountHeader).toHaveAttribute("aria-sort", "ascending");

    let firstRowCells = within(screen.getAllByRole("row")[1]).getAllByRole("cell");
    expect(firstRowCells[1]).toHaveTextContent("$12.00"); // smallest first

    // Toggle to descending.
    await user.click(screen.getByRole("button", { name: /amount/i }));
    expect(amountHeader).toHaveAttribute("aria-sort", "descending");
    firstRowCells = within(screen.getAllByRole("row")[1]).getAllByRole("cell");
    expect(firstRowCells[1]).toHaveTextContent("$24.00"); // largest first
  });
});

