import * as React from "react";

export interface ContainerProps extends React.HTMLAttributes<HTMLElement> {
  as?: React.ElementType;
}

/**
 * The app's main section width. Desktop-first: spans 85% of the viewport,
 * centred, capped at --container-app (1500px) so text lines stay readable for
 * the low-vision audience on very large monitors. Used by the header, the page
 * <main>, and the footer so they all align to the same column.
 */
export function Container({
  as: Tag = "div",
  className = "",
  children,
  ...rest
}: ContainerProps) {
  return (
    <Tag
      className={["mx-auto w-[85%] max-w-app", className]
        .filter(Boolean)
        .join(" ")}
      {...rest}
    >
      {children}
    </Tag>
  );
}

