"use client";

import * as React from "react";
import Link from "next/link";
import { TriangleAlert, RotateCcw, Home } from "lucide-react";
import { Container } from "@/components/shared/Container";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { t } from "@/lib/i18n";

/**
 * Accessible app-wide error boundary. Renders inside the root layout, so the
 * persistent safety affordance stays visible. The message is a live region
 * (role="alert") so screen-reader users hear it; recovery is keyboard-operable.
 */
export default function Error({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  React.useEffect(() => {
    // Surface the error for diagnostics without leaking details to the UI.
    console.error(error);
  }, [error]);

  return (
    <Container as="main" id="main" className="flex-1 py-12 max-md:py-8">
      <Card role="alert" className="mx-auto flex max-w-xl flex-col items-start gap-4">
        <span className="flex items-center gap-2 text-alert">
          <TriangleAlert size={24} strokeWidth={2} aria-hidden="true" />
        </span>
        <h1 className="text-h1">{t("errors.title")}</h1>
        <p className="text-lg text-ink-soft">{t("errors.body")}</p>
        <div className="flex flex-wrap gap-3 pt-2">
          <Button icon={RotateCcw} onClick={() => reset()}>
            {t("errors.retry")}
          </Button>
          <Link href="/" className="rounded-btn">
            <Button variant="ghost" icon={Home}>
              {t("errors.home")}
            </Button>
          </Link>
        </div>
      </Card>
    </Container>
  );
}

