"use client";

import * as React from "react";
import { CircleAlert, CreditCard, ShieldCheck, Check } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Field, Input } from "@/components/ui/Field";
import { createBooking } from "@/app/(customer)/actions";
import { formatCents } from "@/lib/format";
import { t } from "@/lib/i18n";
import { type BlockMinutes } from "@/lib/pricing";

export interface BookingProvider {
  id: string;
  displayName: string;
  prices: Record<BlockMinutes, number>;
  overagePerMinCents: number;
}

const BLOCKS: BlockMinutes[] = [15, 30, 45];

export function BookingForm({
  provider,
  defaultMode,
}: {
  provider: BookingProvider;
  defaultMode: "now" | "scheduled";
}) {
  const [block, setBlock] = React.useState<BlockMinutes>(30);
  const [mode, setMode] = React.useState<"now" | "scheduled">(defaultMode);
  const [scheduledAt, setScheduledAt] = React.useState("");
  const [submitting, setSubmitting] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const [fieldErrors, setFieldErrors] = React.useState<Record<string, string>>({});

  const priceCents = provider.prices[block];

  async function onConfirm() {
    setSubmitting(true);
    setError(null);
    setFieldErrors({});
    const res = await createBooking({
      providerId: provider.id,
      blockMinutes: block,
      startMode: mode,
      scheduledAt:
        mode === "scheduled" && scheduledAt
          ? new Date(scheduledAt).toISOString()
          : undefined,
    });
    // Success redirects; only errors return.
    if (res?.error) {
      setError(res.error);
      setFieldErrors(res.fieldErrors ?? {});
      setSubmitting(false);
    }
  }

  return (
    <div className="flex flex-col gap-6">
      {error ? (
        <p
          role="alert"
          className="flex items-start gap-2 rounded-card border-l-4 border-alert bg-alert-tint px-4 py-3 text-base"
        >
          <CircleAlert size={20} aria-hidden="true" className="mt-0.5 text-alert" />
          {error}
        </p>
      ) : null}

      <fieldset className="flex flex-col gap-3">
        <legend className="text-h3">{t("booking.chooseLength")}</legend>
        <div className="grid grid-cols-3 gap-3 max-sm:grid-cols-1">
          {BLOCKS.map((minutes) => {
            const selected = block === minutes;
            return (
              <label
                key={minutes}
                className={[
                  "flex cursor-pointer flex-col gap-1 rounded-card border bg-surface p-4 has-[:focus-visible]:shadow-[0_0_0_3px_var(--color-focus)]",
                  selected
                    ? "border-2 border-primary bg-primary-tint"
                    : "border-border-strong hover:bg-primary-tint/40",
                ].join(" ")}
              >
                <input
                  type="radio"
                  name="block"
                  value={minutes}
                  checked={selected}
                  onChange={() => setBlock(minutes)}
                  className="sr-only"
                />
                <span className="flex items-center justify-between">
                  <span className="text-lg font-bold text-ink">
                    {t("booking.minutes", { minutes })}
                  </span>
                  {selected ? (
                    <Check size={18} strokeWidth={2.5} aria-hidden="true" className="text-primary" />
                  ) : null}
                </span>
                <span className="text-base font-bold text-ink-soft">
                  {formatCents(provider.prices[minutes])}
                </span>
              </label>
            );
          })}
        </div>
      </fieldset>

      <fieldset className="flex flex-col gap-3">
        <legend className="text-h3">{t("booking.startHeading")}</legend>
        <div className="flex flex-col gap-2">
          {(["now", "scheduled"] as const).map((value) => (
            <label
              key={value}
              className="flex items-center gap-3 rounded-card border border-border-strong bg-surface px-4 py-3 text-base font-bold text-ink has-[:focus-visible]:shadow-[0_0_0_3px_var(--color-focus)]"
            >
              <input
                type="radio"
                name="mode"
                value={value}
                checked={mode === value}
                onChange={() => setMode(value)}
                className="size-5"
              />
              {value === "now" ? t("booking.startNow") : t("booking.startScheduled")}
            </label>
          ))}
        </div>
        {mode === "scheduled" ? (
          <Field label={t("booking.scheduledAtLabel")} error={fieldErrors.scheduledAt} required>
            {(p) => (
              <Input
                {...p}
                type="datetime-local"
                value={scheduledAt}
                onChange={(e) => setScheduledAt(e.target.value)}
              />
            )}
          </Field>
        ) : null}
      </fieldset>

      <section className="flex flex-col gap-2 rounded-card border border-border bg-surface-sunk p-5">
        <h2 className="text-h3">{t("booking.summaryHeading")}</h2>
        <div className="flex items-center justify-between text-base">
          <span className="text-ink">
            {t("booking.summaryBlock", { minutes: block })}
          </span>
          <span className="font-bold text-ink">{formatCents(priceCents)}</span>
        </div>
        <p className="text-sm text-ink-soft">
          {t("booking.summaryOverage", {
            price: formatCents(provider.overagePerMinCents),
          })}
        </p>
        <div className="mt-2 flex items-center justify-between border-t border-border pt-3 text-lg">
          <span className="font-bold text-ink">{t("booking.summaryTotal")}</span>
          <span className="font-bold text-ink">{formatCents(priceCents)}</span>
        </div>
      </section>

      <section className="flex items-center gap-3 rounded-card border border-border bg-surface p-4">
        <CreditCard size={22} aria-hidden="true" className="text-ink-soft" />
        <span className="text-base text-ink">{t("booking.paymentMock")}</span>
      </section>

      <p className="flex items-start gap-2 text-base text-ink-soft">
        <ShieldCheck size={20} aria-hidden="true" className="mt-0.5 flex-none text-primary" />
        {t("booking.reassurance")}
      </p>

      <Button
        full
        onClick={onConfirm}
        disabled={submitting || (mode === "scheduled" && !scheduledAt)}
      >
        {submitting ? t("booking.confirming") : t("booking.confirm")}
      </Button>
    </div>
  );
}

