  });
});

input.new_string:
    process.env.PLATFORM_COMMISSION_RATE = "2";
    expect(getCommissionRate()).toBe(0.05);
  });
});

describe("resolveDonationCents (variable donation, floor = listener rate)", () => {
  it("keeps a donation at or above the floor", () => {
    expect(resolveDonationCents(2400, 2400)).toBe(2400);
    expect(resolveDonationCents(5000, 2400)).toBe(5000);
  });
  it("clamps a below-floor donation up to the floor (protects the listener)", () => {
    expect(resolveDonationCents(1000, 2400)).toBe(2400);
    expect(resolveDonationCents(0, 2400)).toBe(2400);
  });
  it("floors fractional cents and treats invalid input as the floor", () => {
    expect(resolveDonationCents(2400.9, 2400)).toBe(2400);
    expect(resolveDonationCents(NaN, 2400)).toBe(2400);
  });
});

describe("donationPresetsCents", () => {
  it("offers the suggested floor plus two higher whole-dollar options", () => {
    expect(donationPresetsCents(2400)).toEqual([2400, 3600, 4800]);
  });
  it("always includes the floor first and stays at/above it", () => {
    const presets = donationPresetsCents(1050);
    expect(presets[0]).toBe(1050);
    expect(presets.every((c) => c >= 1050)).toBe(true);
    expect([...presets].sort((a, b) => a - b)).toEqual(presets);
  });
});

