"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";

/**
 * Calm fade-and-rise on scroll into view. Used for landing-page sections.
 * Respects prefers-reduced-motion (SPEC §10): then it renders plain, no motion.
 */
export function Reveal({
  children,
  delay = 0,
  className,
}: {
  children: React.ReactNode;
  delay?: number;
  className?: string;
}) {
  const reduce = useReducedMotion();
  // ponytail: reduced-motion users get the static element, nothing fancier.
  if (reduce) return <div className={className}>{children}</div>;
  return (
    <motion.div
      className={className}
      initial={{ opacity: 0, y: 18 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-80px" }}
      transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1], delay }}
    >
      {children}
    </motion.div>
  );
}

