  await shot("account");
  await signOut(page);

  await signIn(page, "maya@heard.test", "password123");
  await page.goto("/provider/dashboard");
  await shot("provider-dashboard");
  await signOut(page);

  await signIn(page, "admin@heard.test", "password123");
  await page.goto("/admin");
  await shot("admin");
});

