import { test, type Page } from "@playwright/test";
import { mkdirSync } from "node:fs";

/**
 * Generates the product screenshot gallery in public/gallery/ used as website
 * visuals. Run on demand: `npx playwright test screenshots` (needs the seed).
 * Captures from seed data only — mutates nothing. Uses generous waits so it
 * survives a cold dev-server compile (unlike the strict shared signIn helper).
 */
const MAYA = "00000000-0000-0000-0000-000000000001";
const DIR = "public/gallery";

async function login(page: Page, email: string) {
  await page.goto("/signin");
  await page.getByLabel(/email address/i).fill(email);
  await page.getByLabel(/^password/i).fill("password123");
  await page.getByRole("button", { name: /^sign in$/i }).click();
  await page.waitForURL((u) => !u.pathname.startsWith("/signin"), {
    timeout: 60_000,
  });
}

async function logout(page: Page) {
  await page.getByRole("button", { name: /sign out/i }).click();
  await page.waitForURL(/\/signin/, { timeout: 60_000 });
}

test("capture product gallery", async ({ page }) => {
  test.setTimeout(300_000);
  mkdirSync(DIR, { recursive: true });
  await page.setViewportSize({ width: 1440, height: 960 });

  const shot = async (name: string) => {
    await page.waitForLoadState("domcontentloaded");
    await page.waitForTimeout(1200); // fonts + reveals settle
    await page.screenshot({ path: `${DIR}/${name}.png` });
  };

  await login(page, "customer@heard.test");
  await page.goto("/browse");
  await shot("browse");
  await page.goto(`/listeners/${MAYA}`);
  await shot("listener");
  await page.goto(`/book/${MAYA}?mode=now`);
  await shot("booking");
  await page.goto("/account");
  await shot("account");
  await logout(page);

  await login(page, "maya@heard.test");
  await page.goto("/provider/dashboard");
  await shot("provider-dashboard");
  await logout(page);

  await login(page, "admin@heard.test");
  await page.goto("/admin");
  await shot("admin");

  await page.goto("/");
  await shot("home");
});

