import { Container } from "@/components/shared/Container";
import { Section } from "@/components/ui/Section";
import { Reveal } from "@/components/motion/Reveal";
import { BrowserFrame } from "@/components/mockups/BrowserFrame";
import { t } from "@/lib/i18n";

const GALLERY = [
  { src: "/gallery/browse.png", key: "marketing.gBrowse", url: "heard.app/browse" },
  { src: "/gallery/listener.png", key: "marketing.gListener", url: "heard.app/listeners" },
  { src: "/gallery/booking.png", key: "marketing.gBooking", url: "heard.app/book" },
  { src: "/gallery/account.png", key: "marketing.gAccount", url: "heard.app/account" },
  { src: "/gallery/provider-dashboard.png", key: "marketing.gProvider", url: "heard.app/dashboard" },
  { src: "/gallery/admin.png", key: "marketing.gAdmin", url: "heard.app/admin" },
] as const;

export function Gallery() {
  return (
    <Section tone="surface" id="gallery" label={t("marketing.galleryHeading")}>
      <Container className="flex flex-col gap-10">
        <Reveal className="flex flex-col gap-1.5">
          <h2 className="text-h2">{t("marketing.galleryHeading")}</h2>
          <p className="max-w-2xl text-lg text-ink-soft">{t("marketing.gallerySub")}</p>
        </Reveal>
        <ul className="grid grid-cols-2 gap-8 max-md:grid-cols-1">
          {GALLERY.map((item, i) => (
            <li key={item.src}>
              <Reveal delay={(i % 2) * 80}>
                <figure className="flex flex-col gap-3 transition-transform duration-300 hover:-translate-y-1">
                  <BrowserFrame url={item.url}>
                    {/* ponytail: plain <img> for local static PNGs; next/image not worth the config. */}
                    {/* eslint-disable-next-line @next/next/no-img-element */}
                    <img
                      src={item.src}
                      alt={t(item.key)}
                      width={1440}
                      height={960}
                      loading="lazy"
                      className="aspect-[3/2] w-full object-cover object-top"
                    />
                  </BrowserFrame>
                  <figcaption className="px-1 text-base font-bold text-ink">
                    {t(item.key)}
                  </figcaption>
                </figure>
              </Reveal>
            </li>
          ))}
        </ul>
      </Container>
    </Section>
  );
}

