import Link from "next/link";
import { Ear, Clock3, HeartHandshake } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Card } from "@/components/ui/Card";
import { Container } from "@/components/shared/Container";
import { Reveal } from "@/components/ui/Reveal";
import { t } from "@/lib/i18n";

const STATS = [
  { valueKey: "marketing.statCallsValue", labelKey: "marketing.statCallsLabel" },
  {
    valueKey: "marketing.statListenersValue",
    labelKey: "marketing.statListenersLabel",
  },
  {
    valueKey: "marketing.statLanguagesValue",
    labelKey: "marketing.statLanguagesLabel",
  },
] as const;

const VALUES = [
  { icon: Ear, titleKey: "marketing.valueListenTitle", bodyKey: "marketing.valueListenBody" },
  { icon: Clock3, titleKey: "marketing.valueControlTitle", bodyKey: "marketing.valueControlBody" },
  { icon: HeartHandshake, titleKey: "marketing.valueDignityTitle", bodyKey: "marketing.valueDignityBody" },
] as const;

const GALLERY = [
  { src: "/gallery/browse.png", key: "marketing.gBrowse" },
  { src: "/gallery/listener.png", key: "marketing.gListener" },
  { src: "/gallery/booking.png", key: "marketing.gBooking" },
  { src: "/gallery/account.png", key: "marketing.gAccount" },
  { src: "/gallery/provider-dashboard.png", key: "marketing.gProvider" },
  { src: "/gallery/admin.png", key: "marketing.gAdmin" },
] as const;

export default function HomePage() {
  return (
    <Container className="flex flex-col gap-24 py-16 max-md:gap-16 max-md:py-10">
      {/* Hero */}
      <section className="relative isolate flex flex-col items-start gap-5 overflow-hidden">
        <div
          aria-hidden="true"
          className="absolute inset-0 -z-10 bg-[radial-gradient(70%_60%_at_25%_-10%,var(--color-primary-tint),transparent_70%),radial-gradient(50%_50%_at_95%_0%,var(--color-accent-tint),transparent_70%)]"
        />
        <Reveal className="flex flex-col items-start gap-5">
          <h1 className="max-w-4xl text-display max-md:text-h1">
            {t("marketing.heroTitle")}
          </h1>
          <p className="max-w-2xl text-lg text-ink-soft">
            {t("marketing.heroSubtitle")}
          </p>
          <div className="flex flex-wrap items-center gap-3 max-sm:w-full max-sm:flex-col max-sm:items-stretch">
            <Link href="/signup" className="rounded-btn transition-transform hover:-translate-y-0.5 max-sm:w-full">
              <Button full className="max-sm:w-full sm:w-auto">
                {t("marketing.ctaPrimary")}
              </Button>
            </Link>
            <Link href="/signin" className="rounded-btn max-sm:w-full">
              <Button variant="ghost" className="max-sm:w-full sm:w-auto">
                {t("nav.signIn")}
              </Button>
            </Link>
          </div>
          <p className="text-base font-semibold text-ink-soft">
            {t("shell.trustLine")}
          </p>
        </Reveal>
      </section>

      {/* Stats */}
      <Reveal>
        <section aria-label={t("marketing.statsHeading")}>
          <Card className="bg-primary-tint">
            <ul className="grid grid-cols-3 gap-6 text-center max-sm:grid-cols-1 max-sm:gap-8">
              {STATS.map(({ valueKey, labelKey }) => (
                <li key={valueKey} className="flex flex-col items-center gap-1">
                  <p className="text-display font-bold text-primary max-md:text-h1">
                    {t(valueKey)}
                  </p>
                  <p className="text-base font-semibold text-ink-soft">{t(labelKey)}</p>
                </li>
              ))}
            </ul>
          </Card>
        </section>
      </Reveal>

      {/* Values */}
      <section aria-label={t("marketing.howItWorks")}>
        <ul className="grid grid-cols-3 gap-5 max-md:grid-cols-1 max-md:gap-4">
          {VALUES.map(({ icon: Icon, titleKey, bodyKey }, i) => (
            <li key={titleKey} className="h-full">
              <Reveal delay={i * 0.08} className="h-full">
                <Card
                  as="div"
                  className="flex h-full flex-col gap-2.5 transition-all duration-300 hover:-translate-y-1 hover:shadow-md"
                >
                  <Icon size={28} strokeWidth={2} aria-hidden="true" className="text-primary" />
                  <h2 className="text-h3">{t(titleKey)}</h2>
                  <p className="text-base text-ink-soft">{t(bodyKey)}</p>
                </Card>
              </Reveal>
            </li>
          ))}
        </ul>
      </section>

      {/* Product gallery */}
      <section className="flex flex-col gap-8" aria-label={t("marketing.galleryHeading")}>
        <Reveal className="flex flex-col gap-1.5">
          <h2 className="text-h2">{t("marketing.galleryHeading")}</h2>
          <p className="max-w-2xl text-lg text-ink-soft">{t("marketing.gallerySub")}</p>
        </Reveal>
        <ul className="grid grid-cols-2 gap-6 max-md:grid-cols-1">
          {GALLERY.map((item, i) => (
            <li key={item.src}>
              <Reveal delay={(i % 2) * 0.08}>
                <figure className="overflow-hidden rounded-card border border-border bg-surface shadow-sm transition-all duration-300 hover:-translate-y-1 hover:shadow-lg">
                  {/* ponytail: plain <img> for local static gallery PNGs; next/image optimization isn't worth the config here. */}
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img
                    src={item.src}
                    alt={t(item.key)}
                    width={1440}
                    height={960}
                    loading="lazy"
                    className="aspect-[3/2] w-full border-b border-border object-cover object-top"
                  />
                  <figcaption className="px-5 py-4 text-base font-bold text-ink">
                    {t(item.key)}
                  </figcaption>
                </figure>
              </Reveal>
            </li>
          ))}
        </ul>
      </section>

      {/* Provider CTA */}
      <Reveal>
        <Card
          as="section"
          className="flex flex-row items-center justify-between gap-5 bg-primary-tint max-md:flex-col max-md:items-start"
        >
          <div className="flex flex-col gap-1">
            <h2 className="text-h3">{t("marketing.providerCtaTitle")}</h2>
            <p className="max-w-2xl text-base text-ink-soft">
              {t("marketing.providerCtaBody")}
            </p>
          </div>
          <Link href="/signup" className="rounded-btn transition-transform hover:-translate-y-0.5 max-md:w-full">
            <Button variant="amber" className="max-md:w-full">
              {t("marketing.becomeListener")}
            </Button>
          </Link>
        </Card>
      </Reveal>
    </Container>
  );
}

